function renderPackages(){el('packageGrid').innerHTML=packages.map(p=>{const sl=p.singleLevels||({BASIC_1:10,BASIC_2:15,ADVANCED_1:20,ADVANCED_2:25,PREMIUM:30}[p.code]);return `<article class="package"><div class="package-top"><span class="pill">${p.code==='PREMIUM'?'MIO only':'MIO or shopping PPV'}</span><h3>${esc(p.name)}</h3></div><div class="pay">${p.payable} <small>MIO Points</small></div><p class="package-cost">${p.base} base + ${p.fee} company fee</p><dl><dt>Personal points · PPV</dt><dd>${p.ppv}</dd><dt>Bonus base · BV</dt><dd>${p.bv}</dd><dt>Direct bonus</dt><dd>${p.direct}%</dd><dt>Generation levels</dt><dd>${p.generations}</dd><dt>Binary placement levels</dt><dd>${sl}</dd><dt>Binary entitlement</dt><dd>${p.entitlement}%</dd></dl><details class="plain-details"><summary>All point allocations</summary><dl><dt>Direct points · DP</dt><dd>${p.dp}</dd><dt>Generation points · GP</dt><dd>${p.gp}</dd><dt>Binary points · BP</dt><dd>${p.bp}</dd><dt>Binary reference · BRP</dt><dd>${p.brp}</dd></dl></details><button class="btn primary activate-package" data-code="${p.code}">Activate ${esc(p.name)}</button><p class="helper">${p.code==='PREMIUM'?'Activate using MIO Points.':'Shopping PPV can also activate this plan automatically.'}</p></article>`}).join('')}

