function catalogRows(items){const more=el('loadMoreProducts'),progress=el('catalogProgress');if(!items.length){el('productsGrid').innerHTML='<div class="empty-card empty" style="grid-column:1/-1"><div class="empty-icon">⌕</div><h3>No approved products yet</h3><p>Check back soon for products from our approved sellers.</p></div>';el('resultCount').textContent='0 products';if(progress)progress.textContent='';if(more)more.classList.add('hidden');return}
 const search=el('searchBox').value.trim().toLowerCase();let rows=items.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&(!search||`${p.name} ${p.description} ${p.category||''} ${p.vendors?.business_name||''}`.toLowerCase().includes(search)));
 const sort=el('sortSelect').value;if(sort==='newest')rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));if(sort==='price-asc')rows.sort((a,b)=>a.price_pkr-b.price_pkr);if(sort==='price-desc')rows.sort((a,b)=>b.price_pkr-a.price_pkr);
 if(sort==='fair'){const groups=new Map();for(const p of rows){const v=p.vendor_id;if(!groups.has(v))groups.set(v,[]);groups.get(v).push(p)}rows=[...groups.values()].flatMap(g=>g.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)));let inter=[];while([...groups.values()].some(g=>g.length))for(const g of groups.values())if(g.length)inter.push(g.shift());const sellers=[...groups.keys()].sort();const offset=sellers.length?Math.floor(Date.now()/86400000)%sellers.length:0;const rotated=sellers.slice(offset).concat(sellers.slice(0,offset));const bins=new Map(rotated.map(v=>[v,inter.filter(p=>p.vendor_id===v)]));rows=[];while([...bins.values()].some(g=>g.length))for(const g of bins.values())if(g.length)rows.push(g.shift())}
 const visible=rows.slice(0,catalogVisibleCount);el('resultCount').textContent=`${rows.length} ${rows.length===1?'product':'products'}`;
 el('productsGrid').innerHTML=visible.length?visible.map(p=>`<article class="product"><div class="product-image">${productImageMarkup(p,p.name)}</div><div class="product-info"><span class="pill">${esc(p.category||'Marketplace')}</span><h3><a href="#product/${p.id}" class="product-title">${esc(p.name)}</a></h3><p>${esc(p.vendors?.business_name||'Approved seller')}</p><div class="product-foot"><span class="price">${retailPriceLabel(p)}${money(p.price_pkr)}${p.ppv_per_unit!==null&&p.ppv_per_unit!==undefined?`<small class="ppv-label">${Number(p.ppv_per_unit).toFixed(2)} PPV</small>`:''}</span><button class="btn primary small add-cart" data-id="${p.id}">Add to basket</button></div></div></article>`).join(''):'<div class="empty-card empty" style="grid-column:1/-1"><h3>No matching products</h3><p>Try another keyword or category.</p></div>';if(progress)progress.textContent=rows.length?`Showing ${visible.length} of ${rows.length} products`:'';if(more){more.classList.toggle('hidden',visible.length>=rows.length);more.textContent=`Load more products (${Math.min(CATALOG_PAGE_SIZE,rows.length-visible.length)} next)`}}
async function loadCatalog(){await loadPlanCatalog();await loadOfflineInstructions();const hero=await db.from('system_config').select('config_value').eq('config_key','MARKETPLACE_HERO').is('effective_to',null).order('version',{ascending:false}).limit(1);heroBanners=Array.isArray(hero.data?.[0]?.config_value)?hero.data[0].config_value:[];renderHeroSlides();const categoryCfg=await db.from('system_config').select('config_value').eq('config_key','MARKETPLACE_CATEGORIES').is('effective_to',null).order('version',{ascending:false}).limit(1);marketplaceCategories=Array.isArray(categoryCfg.data?.[0]?.config_value)?categoryCfg.data[0].config_value:marketplaceCategories;renderProductCategoryOptions(el('prodCategory')?.value||'');await loadPublicAnnouncement();const delivery=await db.from('system_config').select('config_value').eq('config_key','DELIVERY').is('effective_to',null).order('version',{ascending:false}).limit(1);const policy=delivery.data?.[0]?.config_value;deliveryFee=policy?.fee_pkr===null||policy?.fee_pkr===undefined?null:Number(policy.fee_pkr);deliveryPolicy=policy?.policy||'';updateCart();const cfg=await db.from('system_config').select('config_value').eq('config_key','CURRENCY').is('effective_to',null).order('version',{ascending:false}).limit(1);catalogRate=Number(cfg.data?.[0]?.config_value?.usd_to_pkr_rate)||null;el('premiumPurchaseQuote').textContent=catalogRate?'Platinum: '+packages.find(p=>p.code==='PREMIUM').payable+' MIO Points · Current purchase price '+money(packages.find(p=>p.code==='PREMIUM').payable*catalogRate)+'. The rate is saved when you submit the request.':'Platinum purchases await company rate configuration.';let {data,error}=await db.from('products').select('id,vendor_id,name,description,category,image_url,price_pkr,compare_at_price_pkr,ppv_per_unit,image_urls,stock_quantity,created_at,vendors!inner(business_name,status,commission_rate,is_company_owned,logo_url,sale_distribution)').eq('status','approved').gt('stock_quantity',0).eq('vendors.status','active').order('id').range(0,999);if(error){console.error(error);products=[];toast('Marketplace could not load. Refresh in a moment.')}else {products=data||[];let offset=products.length;while(data?.length===1000){const next=await db.from('products').select('id,vendor_id,name,description,category,image_url,price_pkr,compare_at_price_pkr,ppv_per_unit,image_urls,stock_quantity,created_at,vendors!inner(business_name,status,commission_rate,is_company_owned,logo_url,sale_distribution)').eq('status','approved').gt('stock_quantity',0).eq('vendors.status','active').order('id').range(offset,offset+999);if(next.error)throw next.error;data=next.data;products.push(...(data||[]));offset=products.length}}const featuredCfg=await db.from('system_config').select('config_value').eq('config_key','MARKETPLACE_FEATURED_CATEGORIES').is('effective_to',null).order('version',{ascending:false}).limit(1);featuredCategoryConfig=Array.isArray(featuredCfg.data?.[0]?.config_value)?featuredCfg.data[0].config_value:[];const categories=[...new Set(products.map(p=>p.category).filter(Boolean))].sort();el('departments').innerHTML=categories.length?categories.slice(0,8).map(c=>{const count=products.filter(p=>p.category===c).length,meta=marketplaceCategories.find(x=>x.name===c),icon=categoryIcon(meta?.icon||meta?.slug||'beauty');return `<button class="dept" data-pick-category="${esc(c)}"><span class="dept-art"><img src="${icon}" alt="" loading="lazy"></span><strong>${esc(c)}</strong><span>${count} ${count===1?'product':'products'}</span></button>`}).join(''):'<div class="empty-card empty" style="grid-column:1/-1;padding:24px"><div class="empty-icon">⌕</div><h3>Departments are being set up</h3><p>Approved listings will determine the categories shown here.</p></div>';
 el('categoryTabs').innerHTML='<button class="tab active" data-category="all">All products</button>'+categories.map(c=>`<button class="tab" data-category="${esc(c)}">${esc(c)}</button>`).join('');renderFeatured();renderFeaturedCategories();catalogRows(products);renderShopDirectory()}
async function renderFeatured(){const {data,error}=await db.from('featured_products').select('position,product_id').order('position');if(error){console.error(error);return}featuredIds=(data||[]).map(x=>x.product_id);const fp=featuredIds.map(id=>products.find(p=>p.id===id)).filter(Boolean);if(!fp.length){el('featured').innerHTML='<div class="feature-empty">No featured products selected yet<span>Discover our own product picks here soon.</span></div>';return}el('featured').innerHTML=fp.map(p=>`<article class="product"><div class="product-image">${productImageMarkup(p,p.name)}</div><div class="product-info"><span class="pill">Featured by MIO</span><h3><a href="#product/${p.id}" class="product-title">${esc(p.name)}</a></h3><div class="product-foot"><span class="price">${retailPriceLabel(p)}${money(p.price_pkr)}${p.ppv_per_unit!==null&&p.ppv_per_unit!==undefined?`<small class="ppv-label">${Number(p.ppv_per_unit).toFixed(2)} PPV</small>`:''}</span><button class="btn primary small add-cart" data-id="${p.id}">Add</button></div></div></article>`).join('')}
function autoCategoryPicks(category,manualIds=[]){const candidates=products.filter(p=>p.category===category&&Number(p.stock_quantity)>0&&!manualIds.includes(p.id));const ranked=candidates.sort((a,b)=>Number(b.seo_score||b.rating||0)-Number(a.seo_score||a.rating||0)||new Date(b.created_at||0)-new Date(a.created_at||0)||String(a.id).localeCompare(String(b.id)));if(!ranked.length)return[];const day=Math.floor(Date.now()/86400000),count=Math.min(7,ranked.length),start=day%ranked.length;return Array.from({length:count},(_,i)=>ranked[(start+i)%ranked.length])}
function renderFeaturedCategories(){const host=el('featuredCategories');if(!host)return;const groups=featuredCategoryConfig.slice(0,3).map(group=>{const count=products.filter(p=>p.category===group.category&&Number(p.stock_quantity)>0).length,meta=marketplaceCategories.find(x=>x.name===group.category);return{...group,count,icon:categoryIcon(meta?.icon||meta?.slug||'beauty')}}).filter(g=>g.category&&g.count);host.innerHTML=groups.length?groups.map(g=>`<button type="button" class="featured-category-card" data-directory-category="${esc(g.category)}"><span class="featured-category-art"><img src="${g.icon}" alt="" loading="lazy"></span><span class="featured-category-copy"><span class="eyebrow">Featured category</span><strong>${esc(g.category)}</strong><small>${g.count} ${g.count===1?'product':'products'} available</small><b>Explore collection <span aria-hidden="true">→</span></b></span></button>`).join(''):'<div class="feature-empty">Featured category picks will appear here soon.</div>'}
function directoryProductCard(p){return `<article class="product directory-product"><a class="product-image" href="#product/${p.id}">${productImageMarkup(p,p.name)}</a><div class="product-info"><h3><a href="#product/${p.id}" class="product-title">${esc(p.name)}</a></h3><p>${esc(p.vendors?.business_name||'Approved seller')}</p><div class="product-foot"><span class="price">${retailPriceLabel(p)}${money(p.price_pkr)}${p.ppv_per_unit!==null&&p.ppv_per_unit!==undefined?`<small class="ppv-label">${Number(p.ppv_per_unit).toFixed(2)} PPV</small>`:''}</span><button class="btn primary small add-cart" data-id="${p.id}">Add</button></div></div></article>`}
function marketplaceVendors(){const rows=new Map();for(const p of products){const current=rows.get(p.vendor_id)||{id:p.vendor_id,name:p.vendors?.business_name||'Approved seller',logo:p.vendors?.logo_url||'',products:[],categories:new Set()};current.products.push(p);if(p.category)current.categories.add(p.category);rows.set(p.vendor_id,current)}return [...rows.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function renderShopDirectory(){const host=el('shopDirectory');if(!host)return;if(activeShopView==='home'){host.classList.add('hidden');return}host.classList.remove('hidden');if(activeShopView==='vendors'){const vendors=marketplaceVendors();if(activeDirectoryVendor){const vendor=vendors.find(v=>String(v.id)===String(activeDirectoryVendor));host.innerHTML=vendor?`<div class="directory-heading"><div><button class="directory-back" type="button" data-directory-back="vendors">← All vendors</button><div class="eyebrow">Verified marketplace vendor</div><h1>${esc(vendor.name)}</h1><p>${vendor.products.length} products across ${vendor.categories.size} categories.</p></div></div><div class="directory-product-grid">${vendor.products.map(directoryProductCard).join('')}</div>`:'<div class="feature-empty">This vendor has no available products.</div>';return}host.innerHTML=`<div class="directory-heading"><div><div class="eyebrow">Shop by seller</div><h1>All vendors</h1><p>Browse approved marketplace stores and open any vendor to see its products.</p></div><span class="directory-count">${vendors.length} vendors</span></div><div class="vendor-directory-grid">${vendors.map(v=>`<button type="button" class="vendor-directory-card" data-directory-vendor="${esc(v.id)}">${safeImage(v.logo)?`<img src="${safeImage(v.logo)}" alt="${esc(v.name)} logo" loading="lazy">`:`<span class="vendor-monogram">${esc(v.name.slice(0,2).toUpperCase())}</span>`}<strong>${esc(v.name)}</strong><small>${v.products.length} products · ${v.categories.size} categories</small><b>View store <span aria-hidden="true">→</span></b></button>`).join('')||'<div class="feature-empty">Approved vendors will appear here.</div>'}</div>`;return}const categories=[...new Set(products.map(p=>p.category).filter(Boolean))].sort();if(activeDirectoryCategory){const rows=products.filter(p=>p.category===activeDirectoryCategory);host.innerHTML=`<div class="directory-heading"><div><button class="directory-back" type="button" data-directory-back="categories">← All categories</button><div class="eyebrow">Category collection</div><h1>${esc(activeDirectoryCategory)}</h1><p>${rows.length} products from ${new Set(rows.map(p=>p.vendor_id)).size} vendors.</p></div></div><div class="directory-product-grid">${rows.map(directoryProductCard).join('')}</div>`;return}host.innerHTML=`<div class="directory-heading"><div><div class="eyebrow">Browse the marketplace</div><h1>All categories</h1><p>Choose a department to see every available product in it.</p></div><span class="directory-count">${categories.length} categories</span></div><div class="category-directory-grid">${categories.map(c=>{const count=products.filter(p=>p.category===c).length,meta=marketplaceCategories.find(x=>x.name===c);return `<button type="button" class="category-directory-card" data-directory-category="${esc(c)}"><span><img src="${categoryIcon(meta?.icon||meta?.slug||'beauty')}" alt="" loading="lazy"></span><strong>${esc(c)}</strong><small>${count} ${count===1?'product':'products'}</small><b>Shop category <span aria-hidden="true">→</span></b></button>`}).join('')||'<div class="feature-empty">Categories will appear when products are approved.</div>'}</div>`}
function setShopView(view,selection=''){activeShopView=['home','vendors','categories'].includes(view)?view:'home';if(activeShopView==='vendors'){activeDirectoryVendor=selection||'';activeDirectoryCategory=''}else if(activeShopView==='categories'){activeDirectoryCategory=selection||'';activeDirectoryVendor=''}else{activeDirectoryCategory='';activeDirectoryVendor=''}document.querySelectorAll('[data-shop-view]').forEach(b=>{const on=b.dataset.shopView===activeShopView;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});document.querySelectorAll('.shop-home-section').forEach(section=>section.classList.toggle('hidden',activeShopView!=='home'));renderShopDirectory()}
function seedFeaturedCategoryDraft(){const active=adminProductRows.filter(p=>p.status==='approved'&&Number(p.stock_quantity)>0&&adminVendorRows.some(v=>v.id===p.vendor_id&&v.status==='active'));featuredCategoryDraft=(featuredCategoryConfig||[]).slice(0,3).map(group=>{const productIds=[...(group.product_ids||[])].filter(id=>active.some(p=>p.id===id)),selected=active.find(p=>productIds.includes(p.id)),vendor=selected?adminVendorRows.find(v=>v.id===selected.vendor_id):adminVendorRows.find(v=>active.some(p=>p.category===group.category&&p.vendor_id===v.id));return{category:group.category||'',vendorId:vendor?.id||null,productIds}});while(featuredCategoryDraft.length<3)featuredCategoryDraft.push({category:'',vendorId:null,productIds:[]})}
function renderFeaturedAdmin(){const productHost=el('featuredProductManager'),checkHost=el('featuredChecks'),categoryHost=el('featuredCategoryManager');if(!productHost||!checkHost||!categoryHost)return;if(!featuredCategoryDraft.length)seedFeaturedCategoryDraft();const approved=adminProductRows.filter(p=>p.status==='approved'&&Number(p.stock_quantity)>0&&adminVendorRows.some(v=>v.id===p.vendor_id&&v.status==='active'));const vendors=[...new Map(approved.map(p=>[p.vendor_id,adminVendorRows.find(v=>v.id===p.vendor_id)])).values()].filter(Boolean);productHost.innerHTML=`<div class="featured-step"><span class="featured-step-number">1</span><div><strong>Choose a vendor</strong><p>Tap a vendor to see its approved products.</p></div></div><div class="featured-vendor-buttons">${vendors.map(v=>`<button type="button" class="btn small ${activeFeaturedVendor===v.id?'primary':''}" data-feature-product-vendor="${v.id}">${esc(v.business_name)}</button>`).join('')||'<p>No active vendors with in-stock approved products yet.</p>'}</div>`;const productsForVendor=approved.filter(p=>p.vendor_id===activeFeaturedVendor);checkHost.innerHTML=activeFeaturedVendor?(productsForVendor.length?productsForVendor.map(p=>`<article class="feature-choice admin-compact-record"><div class="admin-compact-summary"><label><input type="checkbox" name="featured" value="${p.id}" ${featuredSelectedIds.includes(p.id)?'checked':''}> <strong>${esc(p.name)}</strong></label><button type="button" class="btn small" data-admin-view aria-expanded="false">View</button></div><div class="admin-compact-details" hidden>${safeImage(p.image_url)?`<img class="admin-feature-photo" src="${safeImage(p.image_url)}" alt="${esc(p.name)}">`:''}<p>${esc(p.category||'Uncategorized')} · ${money(p.price_pkr)} · ${esc(adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name||'Vendor')}</p></div></article>`).join(''):'<p>This vendor has no approved in-stock products.</p>'):'<div class="featured-step"><span class="featured-step-number">2</span><div><strong>Products will appear here</strong><p>First choose a vendor above.</p></div></div>';
const catsByVendor=vendorId=>[...new Set(approved.filter(p=>p.vendor_id===vendorId).map(p=>p.category).filter(Boolean))].filter(c=>approved.filter(p=>p.category===c).length>=10).sort();categoryHost.innerHTML=featuredCategoryDraft.map((slot,i)=>{const vendor=adminVendorRows.find(v=>v.id===slot.vendorId);const slotProducts=approved.filter(p=>p.category===slot.category&&p.vendor_id===slot.vendorId);const vendorButtons=vendors.map(v=>`<button type="button" class="btn small ${slot.vendorId===v.id?'primary':''}" data-feature-category-vendor="${i}" data-value="${v.id}">${esc(v.business_name)}</button>`).join('');const categoryButtons=vendor&&catsByVendor(vendor.id).map(c=>`<button type="button" class="chip ${slot.category===c?'active':''}" data-feature-category="${i}" data-value="${esc(c)}">${esc(c)} · ${approved.filter(p=>p.category===c).length}</button>`).join('');return `<article class="featured-category-slot"><h3>Category ${i+1}${slot.category?` · ${esc(slot.category)}`:''}</h3><div class="featured-step"><span class="featured-step-number">1</span><div><strong>Choose a vendor</strong><div class="featured-vendor-buttons">${vendorButtons||'<p>No approved, in-stock products are available yet. Approve a product listing first; then choose its vendor, category and three titles here.</p>'}</div></div></div>${vendor?`<div class="featured-step"><span class="featured-step-number">2</span><div><strong>${esc(vendor.business_name)} · choose one of its categories</strong><div class="featured-category-choices">${categoryButtons||'<p>This vendor has no eligible categories.</p>'}</div></div></div>`:''}${vendor&&slot.category?`<div class="featured-step"><span class="featured-step-number">3</span><div><strong>Select three products from ${esc(slot.category)} · ${approved.filter(p=>p.category===slot.category).length}/10 in-stock products</strong><div class="list">${slotProducts.map(p=>`<article class="feature-choice admin-compact-record"><div class="admin-compact-summary"><label><input type="checkbox" data-feature-category-product="${i}" value="${p.id}" ${slot.productIds.includes(p.id)?'checked':''}> <strong>${esc(p.name)}</strong></label><button type="button" class="btn small" data-admin-view aria-expanded="false">View</button></div><div class="admin-compact-details" hidden>${safeImage(p.image_url)?`<img class="admin-feature-photo" src="${safeImage(p.image_url)}" alt="${esc(p.name)}">`:''}<p>${money(p.price_pkr)} · ${esc(adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name||'Vendor')}</p></div></article>`).join('')||'<p>No approved in-stock products found.</p>'}</div><small>${slot.productIds.length}/3 selected · 7 more rotate automatically. Each category needs 10 approved, in-stock products.</small></div></div>`:''}</article>`}).join('')}
const marketplaceCategoryPack=[{name:'Mobile & Accessories',slug:'mobile-accessories',icon:'mobile-accessories'},{name:'Electronics & Gadgets',slug:'electronics-gadgets',icon:'electronics-gadgets'},{name:'Computers & Gaming',slug:'computers-gaming',icon:'computers-gaming'},{name:'TVs & Home Appliances',slug:'tvs-home-appliances',icon:'tvs-home-appliances'},{name:'Men’s Fashion',slug:'mens-fashion',icon:'mens-fashion'},{name:'Women’s Fashion',slug:'womens-fashion',icon:'womens-fashion'},{name:'Kids & Baby',slug:'kids-baby',icon:'kids-baby'},{name:'Shoes',slug:'shoes',icon:'shoes'},{name:'Peshawari Chappal',slug:'peshawari-chappal',icon:'peshawari-chappal'},{name:'Bags & Luggage',slug:'bags-luggage',icon:'bags-luggage'},{name:'Jewelry & Watches',slug:'jewelry-watches',icon:'jewelry-watches'},{name:'Beauty & Cosmetics',slug:'beauty-cosmetics',icon:'beauty-cosmetics'},{name:'Fragrances',slug:'fragrances',icon:'fragrances'},{name:'Personal Care',slug:'personal-care',icon:'personal-care'},{name:'Winter Wear',slug:'winter-wear',icon:'winter-wear'},{name:'Home & Living',slug:'home-living',icon:'home-living'},{name:'Kitchen & Dining',slug:'kitchen-dining',icon:'kitchen-dining'},{name:'Grocery & Food',slug:'grocery-food',icon:'grocery-food'},{name:'Health & Wellness',slug:'health-wellness',icon:'health-wellness'},{name:'Sports & Fitness',slug:'sports-fitness',icon:'sports-fitness'},{name:'Automotive',slug:'automotive',icon:'automotive'},{name:'Tools & Hardware',slug:'tools-hardware',icon:'tools-hardware'},{name:'Pet Supplies',slug:'pet-supplies',icon:'pet-supplies'},{name:'Books & Stationery',slug:'books-stationery',icon:'books-stationery'}];
function mergeMarketplaceCategories(configured=[]){const rows=[...(Array.isArray(configured)?configured:[]),...marketplaceCategoryPack],seen=new Set();return rows.filter(c=>{const key=String(c?.name||'').trim().toLowerCase();if(!key||seen.has(key))return false;seen.add(key);return true}).map(c=>({...c,icon:c.icon||c.slug}))}
