function normalizeReferralCode(value){return String(value||'').trim().toUpperCase().replace(/^REF-/,'')}
function updateCart(){el('basketCount').textContent=[...cart.values()].reduce((n,x)=>n+x.qty,0);const lines=[...cart.values()];el('cartLines').innerHTML=lines.length?lines.map(x=>`<div class="list-row"><div><strong>${esc(x.product.name)}</strong><small>${money(x.product.price_pkr)} each</small></div><div style="display:flex;align-items:center;gap:7px"><button class="btn small qty" data-id="${x.product.id}" data-delta="-1">−</button><b>${x.qty}</b><button class="btn small qty" data-id="${x.product.id}" data-delta="1">+</button><button class="btn small" data-remove="${x.product.id}">Remove</button></div></div>`).join(''):'<div class="empty" style="padding:18px"><h3>Your basket is empty</h3><p>Add a real product from the marketplace.</p></div>';const total=lines.reduce((s,x)=>s+Number(x.product.price_pkr)*x.qty,0);const discount=lines.reduce((n,x)=>{const gross=Number(x.product.price_pkr)*x.qty;const pool=Math.round((gross*Number(x.product.vendors?.commission_rate||0)+Number.EPSILON)*100)/100;const company=Math.round((gross*0.05+Number.EPSILON)*100)/100;return n+Math.min(Math.round((gross*Number(x.product.vendors?.sale_distribution?.buyer_discount||0)/100+Number.EPSILON)*100)/100,Math.max(0,pool-company))},0);const retailSaving=lines.reduce((n,x)=>n+Math.max(Number(x.product.compare_at_price_pkr||0)-Number(x.product.price_pkr),0)*x.qty,0);el('cartRetailSaving').textContent=retailSaving?'Product sale savings: '+money(retailSaving)+' · Already included in the prices shown.':'';el('cartSubtotal').textContent=money(total);el('cartDiscount').textContent='Buyer discount: '+money(discount)+' · Products after discount: '+money(total-discount);el('deliverySummary').textContent=deliveryFee===null?'Delivery charges are awaiting company configuration.':'Shipping: '+money(deliveryFee)+' · Order total: '+money(total-discount+deliveryFee)+'. '+deliveryPolicy;el('checkoutForm').classList.toggle('hidden',!lines.length);syncCheckoutIdentity()}
const GUEST_ORDERS_KEY='mio-guest-orders';
function guestOrders(){try{return JSON.parse(localStorage.getItem(GUEST_ORDERS_KEY)||'[]').filter(x=>x&&x.order_code&&x.access_token)}catch{return[]}}
function guestRoute(code){return 'guest-'+encodeURIComponent(String(code||'').toUpperCase())}
function guestOrderFromRoute(id){if(!String(id||'').startsWith('guest-'))return null;const code=decodeURIComponent(String(id).slice(6)).toUpperCase();return guestOrders().find(x=>String(x.order_code).toUpperCase()===code)||null}
function canOpenGuestOrder(id){return !!guestOrderFromRoute(id)}
function rememberGuestOrder(order_code,access_token){const code=String(order_code||'').toUpperCase(),orders=[{order_code:code,access_token,created_at:new Date().toISOString()},...guestOrders().filter(x=>String(x.order_code).toUpperCase()!==code)].slice(0,20);localStorage.setItem(GUEST_ORDERS_KEY,JSON.stringify(orders));return orders[0]}
function guestAccessToken(){const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
async function fetchGuestOrder(entry){const {data,error}=await db.rpc('guest_order_status',{p_order_code:entry.order_code,p_access_token:entry.access_token});if(error)throw error;return data}
function syncCheckoutIdentity(){const form=el('checkoutForm');if(!form)return;const affiliateGuest=!!currentSellingCode(),guestCheckout=!session||affiliateGuest;let field=el('guestEmailField');if(!field){field=document.createElement('div');field.className='field guest-checkout-field';field.id='guestEmailField';field.innerHTML='<label for="guestEmail">Email for guest order tracking</label><input id="guestEmail" type="email" autocomplete="email"><small>Your private receipt link stays on this device. No MIO account or team registration will be created.</small>';form.insertBefore(field,el('shipName')?.closest('.field')||form.querySelector('.field'))}field.classList.toggle('hidden',!guestCheckout);el('guestEmail')?.toggleAttribute('required',guestCheckout);const submit=form.querySelector('button[type="submit"]');if(submit)submit.textContent=guestCheckout?'Place guest COD order':'Place COD order';if(guestCheckout)el('checkoutRewardNote').textContent=affiliateGuest?'Affiliate link checkout is guest-only. The selling member must approve the order with a refundable 2 MIO hold. No account will be created.':'Guest checkout is for shopping only. No PPV, MIO wallet or team account will be created.'}
async function loadGuestOrders(){const target=el('ordersTable'),orders=guestOrders();if(!target)return;if(!orders.length){target.innerHTML='<div class="empty"><h3>Guest orders</h3><p>You can shop without joining. Guest receipts are saved privately on this device.</p><button class="btn primary" data-page="shop">Start shopping</button></div>';return}target.innerHTML='<div class="empty" style="padding:18px"><h3>Loading guest orders…</h3></div>';const rows=[];for(const entry of orders){try{rows.push(await fetchGuestOrder(entry))}catch{}}target.innerHTML=rows.length?`<table><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th>Reward note</th></tr></thead><tbody>${rows.map(o=>`<tr><td><a href="#order/${guestRoute(o.order_code)}">${esc(o.order_code)}</a></td><td>${new Date(o.created_at).toLocaleDateString()}</td><td>${money(o.total_pkr)}</td><td>${esc(o.payment_method)} · ${esc(o.payment_status)}</td><td>${orderStatus(o.status)}</td><td>${o.affiliate_attributed?'Affiliate reward is tracked for seller':'Guest order · no member rewards'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h3>Guest order receipts unavailable</h3><p>Use the same device and browser that placed the guest order.</p></div>'}
