function renderBinaryCycleHistory(cycles){const host=el('binaryCycleHistory');if(!host)return;host.innerHTML=cycles?.length?cycles.map(c=>`<article class="list-row"><div><strong>${esc(c.cycle_code)}</strong><small>${new Intl.DateTimeFormat('en-PK',{dateStyle:'medium',timeZone:'Asia/Karachi'}).format(new Date(c.ends_at))} · ${esc(c.status)} · ${Number(c.total_completed_shares||0).toFixed(1)} shares paid · ${Number(c.pool_amount||0).toFixed(2)} MIO distributed</small></div></article>`).join(''):'<p>No binary share distribution has been posted yet.</p>'}
function renderBinaryPoolAdmin(d){const card=el('binaryCycleHistory')?.closest('.card');if(!card||!d)return;const threshold=Number(d.share_points_each_side||50);card.querySelector('.card-head').innerHTML=`<div><h2>Weekly Binary Pool</h2><p id="binaryPoolSummary">Manual distribution. One full share currently needs ${threshold} BP LEFT and ${threshold} BP RIGHT; unmatched points carry forward.</p></div><span class="status-pill">Manual</span>`;let panel=el('binaryPoolAdminPanel');if(!panel){panel=document.createElement('div');panel.id='binaryPoolAdminPanel';card.querySelector('.card-body').prepend(panel)}const rows=Array.isArray(d.shares_by_package)?d.shares_by_package:[],period=`${dateLabel(d.period_start)} to ${dateLabel(d.period_end)}`,shares=Number(d.total_shares||0),sharePrice=Number(d.default_share_value||0),defaultTotal=sharePrice*shares;panel.innerHTML=`<button type="button" class="accounting-metric wide-metric" id="binaryPoolAdminToggle" aria-expanded="false"><span>Binary Pool</span><b>${shares} shares · ${mioFmt(d.total_pool_wallet)}</b><small>Click to open wallet, share price, completed-share setting and distribution details</small></button><div id="binaryPoolDetails" class="hidden"><div class="accounting-grid binary-pool-grid"><button type="button" class="accounting-metric"><span>Total binary pool wallet</span><b>${mioFmt(d.total_pool_wallet)}</b><small>Reserved MIO held for binary pool</small></button><button type="button" class="accounting-metric"><span>This week pool</span><b>${mioFmt(d.this_week_pool)}</b><small>${esc(period)}</small></button><button type="button" class="accounting-metric"><span>Last week distributed</span><b>${mioFmt(d.last_week_distributed)}</b><small>Most recent posted cycle</small></button><button type="button" class="accounting-metric" id="binaryShareDetailsToggle"><span>Total shares</span><b>${shares}</b><small>${threshold} BP left + ${threshold} BP right per share</small></button></div><form id="binarySharePointsForm" class="form binary-pool-form"><div class="row"><label>BP needed on LEFT for 1 share<input id="binarySharePoints" type="number" min="1" max="1000000" step="0.0001" value="${threshold.toFixed(4)}"></label><label>BP needed on RIGHT for 1 share<input type="text" value="Same as left side" readonly></label></div><button class="btn">Save share completion rule</button><p class="helper">Example: 10 means 10 BP LEFT + 10 BP RIGHT = 1 completed binary pool share.</p></form><div id="binaryShareDetails" class="history-table-scroll hidden"><table class="compact-history"><thead><tr><th>Package</th><th class="numeric">Completed shares</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(planName(r.package_code))}</td><td class="numeric">${Number(r.shares||0)}</td></tr>`).join(''):'<tr><td colspan="2">No package has completed shares yet.</td></tr>'}</tbody></table></div><form id="binaryPoolDistributeForm" class="form binary-pool-form" data-shares="${shares}"><div class="row"><label>Share price per completed share (MIO)<input id="binaryPoolSharePrice" type="number" min="0" step="0.0001" value="${sharePrice.toFixed(4)}" ${d.can_distribute?'':'disabled'}></label><label>Total payout preview<input id="binaryPoolPayoutPreview" type="text" value="${mioFmt(defaultTotal)}" readonly></label></div><button class="btn primary" ${d.can_distribute?'':'disabled'}>Distribute Binary Pool</button><p class="helper">${d.can_distribute?'The administrator sets only the share price. The system distributes the total payout as share price × total completed shares.':'Distribution unlocks after the 7-day period is complete and at least one full share exists.'}</p></form></div>`}
