async function loadTickets(){if(!isAdmin)return;const {data,error}=await db.from('support_tickets').select('id,email,message,status,response,created_at').order('created_at',{ascending:false}).limit(100);if(error)throw error;if(!isAdmin)return;el('workspaceTickets').innerHTML=data?.length?data.map(t=>`<form class="form ticket-answer" data-id="${t.id}"><strong>${esc(t.email)} · ${esc(t.status)}</strong><small>${new Date(t.created_at).toLocaleString()}</small><p>${esc(t.message)}</p><label>Reply<textarea required minlength="10" maxlength="4000">${esc(t.response||'')}</textarea></label><label><input type="checkbox" name="close"> Close ticket</label><button class="btn primary">Send reply</button></form>`).join(''):'<p>No recovery tickets yet.</p>';el('workspaceTickets').querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();submit(form,async()=>{const {error}=await db.rpc('answer_recovery_ticket',{p_ticket_id:form.dataset.id,p_response:form.querySelector('textarea').value.trim(),p_close:form.querySelector('input[name="close"]').checked});if(error)throw error;toast('Reply saved for the ticket holder');await loadTickets()})}))}
