const exportKeys={shopping_reward_events:'order_id',commission_allocations:'id',vendor_applications:'id',premium_purchase_requests:'id',member_profiles:'user_id',binary_placements:'member_id',vendor_income_ledger:'id',vendor_withdrawals:'id',vendors:'id',products:'id',package_versions:'package_code',system_config:'config_key',package_activations:'id',point_ledger:'id',mio_wallet_accounts:'member_id',mio_ledger:'id',bonus_transactions:'id',binary_cycles:'id',binary_member_results:'cycle_id',orders:'id',order_items:'id',audit_logs:'id'};
async function readDataset(table){if(!isAdmin||!exportKeys[table])throw Error('Workspace access required');let rows=[],offset=0;for(;;){const {data,error}=await db.from(table).select('*').order(exportKeys[table]).order(table==='package_versions'||table==='system_config'?'version':table==='binary_member_results'?'member_id':exportKeys[table]).range(offset,offset+999);if(error)throw error;if(!isAdmin)throw Error('Session ended');rows.push(...(data||[]));if(!data||data.length<1000)return rows;offset+=1000}}
function showOperationsMembers(){const search=el('memberSearch').value.trim().toLowerCase();const rows=operationsMembers.filter(m=>[m.full_name,m.member_code,m.referral_code].some(v=>String(v||'').toLowerCase().includes(search))).slice(0,100);el('workspaceMembers').innerHTML=rows.length?`<table><thead><tr><th>Member</th><th>Code</th><th>Status</th><th>Sponsor</th><th>Joined</th><th>Manage</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.full_name)}</td><td>${esc(m.member_code)}</td><td>${esc(m.status)}</td><td>${esc(operationsMembers.find(s=>s.user_id===m.sponsor_id)?.member_code||'—')}</td><td>${new Date(m.created_at).toLocaleDateString()}</td><td><button class="btn small edit-member" data-id="${m.user_id}">Edit account</button></td></tr>`).join('')}</tbody></table><p class="helper">Showing up to 100 matches. Exports include all records.</p>`:'<p>No matching members.</p>'}
function renderAdminMembershipSummary(members,activations){
 const host=el('adminMembershipSummary');if(!host||!isAdmin)return;
 const latest=new Map;for(const row of activations)latest.set(row.member_id,row.package_code);
 const counts=new Map([['free',0],...packages.map(p=>[p.code,0])]);
 const enrolled=members.filter(m=>m.user_id!==session?.user.id).sort((a,b)=>(Date.parse(a.created_at)||0)-(Date.parse(b.created_at)||0)||String(a.user_id).localeCompare(String(b.user_id))).map((m,i)=>({...m,serial:i+1,package:latest.get(m.user_id)||'free'}));
 for(const member of enrolled)counts.set(member.package,(counts.get(member.package)||0)+1);
 const tiers=[['free','Free'],...packages.map(p=>[p.code,p.name]),...[...counts.keys()].filter(code=>code!=='free'&&!packages.some(p=>p.code===code)).map(code=>[code,planName(code)])];
 host.innerHTML=`<button type="button" class="admin-membership-total" data-member-tier="all" aria-expanded="false" aria-controls="adminMembershipDetails"><span>Total members</span><strong>${enrolled.length}</strong><small>Registered members · company account excluded · View members</small></button><div class="admin-membership-tiers">${tiers.map(([code,label])=>`<button type="button" class="admin-membership-tier" data-member-tier="${esc(code)}" aria-expanded="false" aria-controls="adminMembershipDetails"><span>${esc(label)}</span><b>${counts.get(code)||0}</b></button>`).join('')}</div><p class="helper">Select a count to view members. Each member appears under their latest approved package; no approved package means Free.</p><section id="adminMembershipDetails" class="admin-membership-details" hidden></section>`;
 let selected='all',page=1;
 const showMembers=()=>{
  if(!isAdmin||!session)return;
  const rows=enrolled.filter(m=>selected==='all'||m.package===selected).slice().reverse(),size=50,pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(Math.max(1,page),pages);
  const label=selected==='all'?'All members':tiers.find(t=>t[0]===selected)?.[1]||selected,details=host.querySelector('#adminMembershipDetails');details.hidden=false;
  const dayOf=m=>m.created_at?historyDay(m.created_at):'',dayCounts=new Map;for(const m of rows){const day=dayOf(m);dayCounts.set(day,(dayCounts.get(day)||0)+1)}let previousDay=null;
  const body=rows.slice((page-1)*size,page*size).map(m=>{const day=dayOf(m),heading=day!==previousDay?`<tr class="membership-date"><th colspan="6" scope="rowgroup">${day?esc(enrollmentDateLabel(day)):'Joining date unavailable'} · Members: ${dayCounts.get(day)}</th></tr>`:'';previousDay=day;return heading+`<tr><td>${m.serial}</td><td>${esc(m.member_code||'—')}</td><td>${esc(m.full_name||'Member unavailable')}</td><td>${esc(m.package==='free'?'Free':planName(m.package))}</td><td>${esc(m.status||'—')}</td><td>${day?esc(enrollmentDateLabel(day)):'—'}</td></tr>`}).join('');
  details.innerHTML=`<div class="membership-details-heading"><h3>${esc(label)} · ${rows.length} members</h3><button type="button" class="btn small" data-member-close>Close</button></div><div class="table-wrap"><table class="compact-history"><thead><tr><th>S/No</th><th>MIO ID</th><th>Name</th><th>Package</th><th>Status</th><th>Joined</th></tr></thead><tbody>${body||'<tr><td colspan="6">No members in this category.</td></tr>'}</tbody></table></div>${pages>1?`<div class="package-report-pagination"><span>Page ${page} of ${pages}</span><button type="button" class="btn small" data-member-page="-1" ${page===1?'disabled':''}>Previous</button><button type="button" class="btn small" data-member-page="1" ${page===pages?'disabled':''}>Next</button></div>`:''}`;
  host.querySelectorAll('[data-member-tier]').forEach(button=>{const active=button.dataset.memberTier===selected;button.classList.toggle('active',active);button.setAttribute('aria-expanded',String(active))});
  details.querySelector('[data-member-close]').onclick=()=>{details.hidden=true;host.querySelectorAll('[data-member-tier]').forEach(button=>{button.classList.remove('active');button.setAttribute('aria-expanded','false')})};
  details.querySelectorAll('[data-member-page]').forEach(button=>button.onclick=()=>{page+=Number(button.dataset.memberPage);showMembers()});enhanceResponsiveTables(details);
 };
 host.querySelectorAll('[data-member-tier]').forEach(button=>button.onclick=()=>{selected=button.dataset.memberTier;page=1;showMembers()});
}
async function loadAdminMembershipSummary(){const uid=session?.user.id;const [members,activations]=await Promise.all([readDataset('member_profiles'),fetchPackageActivations()]);if(isAdmin&&session?.user.id===uid)renderAdminMembershipSummary(members,activations)}
async function loadOperationsMembers(){operationsMembers=await readDataset('member_profiles');showOperationsMembers()}
async function loadOperationsReport(){if(!isAdmin)return;const {data,error}=await db.rpc('operations_report');if(error)throw error;if(!isAdmin)return;el('operationsReport').innerHTML=`<table><tbody>${Object.entries(data||{}).map(([key,value])=>`<tr><th>${esc(key.replaceAll('_',' '))}</th><td>${esc(typeof value==='object'?JSON.stringify(value):String(value))}</td></tr>`).join('')}</tbody></table>`}
el('memberSearch').addEventListener('input',showOperationsMembers);el('refreshReport').addEventListener('click',()=>loadOperationsReport().catch(e=>toast(e.message)));
function exportText(rows,format){if(format==='json')return JSON.stringify(rows,null,2);const keys=[...new Set(rows.flatMap(row=>Object.keys(row)))];const cell=value=>{let text=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};return [keys.map(cell).join(','),...rows.map(row=>keys.map(key=>cell(row[key])).join(','))].join('\r\n')}
el('exportForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const dataset=el('exportDataset').value,format=el('exportFormat').value;const rows=await readDataset(dataset);const blob=new Blob([exportText(rows,format)],{type:format==='json'?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mio-'+dataset+'-'+new Date().toISOString().slice(0,10)+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded: '+rows.length+' records')})});
document.addEventListener('submit',e=>{if(!e.target.matches('.inventory-form'))return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.rpc('update_seller_inventory',{p_product_id:form.dataset.id,p_price:Number(form.elements.price.value),p_stock:Number(form.elements.stock.value)});if(error)throw error;toast('Inventory saved. Price changes require listing review.');await loadSellerProducts(form.dataset.vendor);await loadCatalog()})});
