function renderGenerationLevels(q){const target=generationLevelPanel();if(!target)return;const allowed=Number(q?.allowed_levels||0),unlocked=Number(q?.unlocked_levels||0),directs=Number(q?.active_directs||0),dp=Number(q?.working_dp||0),packageName=q?.package_name||'Free account',wasOpen=target.querySelector('[data-generation-details]')&&!target.querySelector('[data-generation-details]').hidden;const levels=Array.from({length:10},(_,i)=>{const level=i+1,state=level<=unlocked?'unlocked':level<=allowed?'pending':'locked',label=state==='unlocked'?'Unlocked':state==='pending'?'Qualification pending':'Not in package';return `<div class="generation-level ${state}" title="Level ${level}: ${label}"><span>${state==='locked'?'🔒':level}</span><small>L${level}</small></div>`}).join('');const next=unlocked>=allowed?(allowed?'All package levels unlocked':'Activate a plan to unlock generation levels'):`Next: ${Math.floor(unlocked/2)+1} active direct(s) + ${(Math.floor(unlocked/2)+1)*20} DP`;target.innerHTML=`<button type="button" class="generation-level-toggle" data-generation-toggle aria-expanded="${wasOpen?'true':'false'}"><span><b>Levels</b><small>${esc(packageName)} · ${unlocked}/${allowed} unlocked</small></span><strong>${wasOpen?'Close':'View'}⌄</strong></button><div class="generation-level-details" data-generation-details ${wasOpen?'':'hidden'}><div class="generation-level-head"><div><small>Generation access</small><strong>${unlocked} of ${allowed} levels unlocked</strong></div><div><span>${directs} active direct${directs===1?'':'s'}</span><span>${dp.toFixed(2)} working DP</span></div></div><div class="generation-levels">${levels}</div><p>${esc(next)}. Green = unlocked, grey = qualification pending, lock = higher package required.</p></div>`}
