async function loadNetworkViews(){if(!session||!profile)return;let all=el('networkDepth').querySelector('[value="0"]');if(isAdmin&&!all){all=document.createElement('option');all.value='0';all.textContent='All levels · master';el('networkDepth').append(all)}else if(!isAdmin&&all){if(el('networkDepth').value==='0')el('networkDepth').value='10';all.remove()}const links=!isAdmin&&!['active','inactive'].includes(profile.status)?'<p>Complete registration to continue.</p>':isAdmin?'<p>Company has one direct founder: SHUJAAT ALI KHAN. Company has no LEFT/RIGHT referral links.</p>':!hasApprovedPackage?'<section class="referral-lock-card"><span class="pill">Team access locked</span><h3>Activate a plan to build your team</h3><p>Your free account remains visible in the Direct and Generation network. Left/Right referral links and Binary placement unlock after any plan is activated.</p><button class="btn primary" data-page="packages">Explore membership plans</button></section>':['LEFT','RIGHT'].map(side=>{const code='REF-'+profile.referral_code+'-'+side[0],url=location.origin+location.pathname+'?ref='+encodeURIComponent(code)+'#join';return `<section class="referral-tile"><h3>${side} referral</h3><p class="code">${esc(code)}</p><p class="referral-url">${esc(url)}</p><button class="btn small copy-code" data-copy="${esc(code)}">Copy code</button> <button class="btn primary small copy-code" data-copy="${esc(url)}">Copy link</button><small>Joins your ${side.toLowerCase()}most line. You remain the sponsor.</small></section>`}).join('');el('profileCard').innerHTML=`<div class="network-profile-heading">${safeImage(profile.profile_photo_url)?`<img class="network-profile-photo" src="${safeImage(profile.profile_photo_url)}" alt="${esc(profile.full_name)} profile">`:''}<div><h3>${esc(profile.full_name)}</h3><p class="code">${esc(profile.member_code)}</p></div></div><label class="profile-photo-upload">Profile picture <input id="profilePhotoUpload" type="file" accept="image/jpeg,image/png,image/webp"><small>Upload a square photo (JPG, PNG or WebP, max 5 MB). It appears on your tree.</small></label><div class="referral-links">${links}</div>${sellingLinks()}`;await renderNetwork()}
function syncNetworkDepthOptions(kind){const select=el('networkDepth'),placement=kind==='single_line';for(const depth of [15,20,25,30]){let option=select.querySelector(`[value="${depth}"]`);if(!option){option=document.createElement('option');option.value=String(depth);option.textContent=String(depth);option.dataset.placementDepth='true';select.append(option)}option.hidden=!placement;option.disabled=!placement}if(placement&&Number(select.value)<30)select.value='30';if(!placement&&Number(select.value)>10)select.value='10'}
async function renderNetwork(){if(!session)return;const turn=++networkRequest,uid=session.user.id,kind=el('networkKind').value;syncNetworkDepthOptions(kind);document.querySelectorAll('[data-network-kind]').forEach(t=>{const selected=t.dataset.networkKind===kind;t.classList.toggle('active',selected);t.setAttribute('aria-selected',String(selected))});el('networkVisual').textContent='Loading your network…';const {data,error}=await db.rpc('my_network',{p_kind:kind,p_root_code:networkRoot,p_depth:Number(el('networkDepth').value)});if(turn!==networkRequest||session?.user.id!==uid)return;if(error){el('networkVisual').textContent='Could not load network.';throw error}const nodes=data?.nodes||[];el('networkExplanation').textContent=({generation:'Generation / Uni-level tree · follows the sponsor chain, one generation per level.',binary:'Binary tree · members are arranged by LEFT and RIGHT placement.',single_line:'Binary placement tree · all 30 levels remain visible; earning levels follow the active package.',vendor:'Vendor tree · vendors referred by you or the selected member.'})[kind];el('networkBack').disabled=!networkHistory.length;
drawNetwork(nodes,kind,data);}

el('networkKind').addEventListener('change',()=>{networkRoot=null;networkHistory=[];selectedTreeNodeId=null;el('treeMemberDetails').innerHTML='<div class="tree-detail-empty"><span>◎</span><strong>Select a member</strong><small>Member and team details will appear here.</small></div>';renderNetwork().catch(e=>toast(e.message))});document.querySelectorAll('[data-network-kind]').forEach(t=>t.addEventListener('click',()=>{el('networkKind').value=t.dataset.networkKind;el('networkKind').dispatchEvent(new Event('change'))}));el('networkDepth').addEventListener('change',()=>renderNetwork().catch(e=>toast(e.message)));el('networkHome').addEventListener('click',()=>{networkRoot=null;networkHistory=[];selectedTreeNodeId=null;el('treeMemberDetails').innerHTML='<div class="tree-detail-empty"><span>i</span><strong>Select a member</strong><small>Member and team details will appear here.</small></div>';renderNetwork().catch(e=>toast(e.message))});el('networkBack').addEventListener('click',()=>{networkRoot=networkHistory.pop()||null;selectedTreeNodeId=null;el('treeMemberDetails').innerHTML='<div class="tree-detail-empty"><span>i</span><strong>Select a member</strong><small>Member and team details will appear here.</small></div>';renderNetwork().catch(e=>toast(e.message))});el('networkVisual').addEventListener('click',e=>{const b=e.target.closest('[data-tree-root]');if(b&&b.dataset.treeRoot!==networkRoot){networkHistory.push(networkRoot);networkRoot=b.dataset.treeRoot;renderNetwork().catch(e=>toast(e.message))}});
async function loadSellerAccount(vid){const uid=session?.user.id;const [summary,ledger,withdrawals]=await Promise.all([db.rpc('my_brand_summary',{p_vendor_id:vid}),db.from('vendor_income_ledger').select('*').eq('vendor_id',vid).order('created_at',{ascending:false}).limit(100),db.from('vendor_withdrawals').select('id,amount_pkr,status,review_note,created_at').eq('vendor_id',vid).order('created_at',{ascending:false}).limit(100)]);const error=[summary,ledger,withdrawals].find(r=>r.error)?.error;if(error)throw error;if(!session||session.user.id!==uid)return;const s=summary.data;if(!s)return;const available=Number(s.income_pkr)-Number(s.reserved_pkr)-Number(s.paid_pkr);el('sellerSummary').innerHTML=[['Confirmed sales',s.sales_pkr],['Your income',s.income_pkr],['Available to withdraw',available],['Reserved withdrawals',s.reserved_pkr],['Withdrawals paid',s.paid_pkr]].map(([title,value])=>`<section class="card metric"><span>${title}</span><b>${money(value)}</b></section>`).join('');el('sellerSales').innerHTML=ledger.data?.length?`<table><thead><tr><th>Date</th><th>Sale</th><th>Company commission</th><th>Your income</th></tr></thead><tbody>${ledger.data.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString()}</td><td>${money(r.gross_pkr)}</td><td>${money(r.commission_pkr)}</td><td>${money(r.net_pkr)}</td></tr>`).join('')}</tbody></table>`:'<p>No confirmed sales yet.</p>';el('sellerWithdrawals').innerHTML=withdrawals.data?.length?withdrawals.data.map(r=>`<div class="list-row"><strong>${money(r.amount_pkr)}</strong><span>${esc(r.status)}</span><small>${esc(r.review_note||'Awaiting company review')}</small></div>`).join(''):'<p>No withdrawal requests.</p>'}
el('vendorWithdrawalForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const {error}=await db.rpc('request_brand_withdrawal',{p_vendor_id:el('sellerBrand').value,p_amount:el('withdrawAmount').value,p_bank:el('withdrawBank').value.trim(),p_account_name:el('withdrawName').value.trim(),p_account_number:el('withdrawAccount').value.trim(),p_idempotency_key:idKey()});if(error)throw error;form.reset();toast('Withdrawal request sent to operations');await loadMember()})});
async function loadWithdrawalApprovals(){if(!isAdmin)return;const {data,error}=await db.from('vendor_withdrawals').select('*').in('status',['pending','approved']).order('created_at').limit(100);if(error)throw error;if(!isAdmin)return;el('withdrawalApprovals').innerHTML=data?.length?data.map(r=>`<form class="form withdrawal-review" data-id="${r.id}"><strong>${esc(adminVendorRows.find(v=>v.id===r.vendor_id)?.business_name||'Seller')} · ${money(r.amount_pkr)} · ${esc(r.status)}</strong><p>${esc(r.bank_name)} · ${esc(r.account_name)} · ${esc(r.account_number)}</p><label>Decision<select name="decision">${r.status==='pending'?'<option value="approved">Approve request</option>':'<option value="paid">Mark paid after bank payment</option>'}<option value="rejected">Reject / release reservation</option></select></label><label>Payment reference / decision note<textarea name="note" required minlength="10" maxlength="2000"></textarea></label><button class="btn primary">Verify & save decision</button></form>`).join(''):'<p>No seller withdrawals awaiting review.</p>'}
document.addEventListener('submit',e=>{if(!e.target.matches('.withdrawal-review'))return;e.preventDefault();const form=e.target;submit(form,async()=>{await confirmSensitive('Record seller withdrawal decision: '+form.elements.decision.value);const {error}=await db.rpc('review_vendor_withdrawal',{p_request_id:form.dataset.id,p_status:form.elements.decision.value,p_note:form.elements.note.value.trim()});if(error)throw error;toast('Withdrawal decision recorded');await loadWithdrawalApprovals()})});
async function loadCompanySummary(){const {data,error}=await db.rpc('company_network_summary');if(error)throw error;if(!isAdmin)return;el('companyNetworkSummary').innerHTML=`<p>Sole founder: <strong>${esc(data?.founder||'Not configured')}</strong></p><p>Binary company retention: ${Number(data?.binary_retention_mio||0).toFixed(2)} MIO</p><p>Package company fees: ${Number(data?.package_fees_mio||0).toFixed(2)} MIO</p><p>Company earnings from vendors: ${money(data?.seller_commission_pkr)}</p>`}
