el('mioReferencePriceForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{if(!isAdmin)throw Error('Admin account required');const price=Number(el('mioReferencePriceInput').value);if(!Number.isFinite(price)||price<=0||price>1000000||Math.round(price*100)!==price*100)throw Error('Enter a valid PKR price with up to two decimals');await confirmSensitive('Set the MIO reference price to '+money(price)+' per MIO');const {data,error}=await db.rpc('admin_set_mio_reference_price',{p_price:price});if(error)throw error;mioReferencePricePkr=Number(data?.price_pkr??price);updateMioReferencePrice();toast('MIO reference price saved')})});
function showWorkspace(key){if(!panels.has(key))return;if(key==='ecommerce'&&isAdmin)loadEcommerce().catch(e=>toast(e.message));const featuredCard=el('featuredContentToggle')?.closest('.card'),binaryCard=el('binaryCycleHistory')?.closest('.card');if(key==='storefront'&&featuredCard)panels.get(key).prepend(featuredCard);if(key==='binary-pool'&&binaryCard)panels.get(key).prepend(binaryCard);const section=workspaceSections.find(item=>item[0]===key);heading.querySelector('h1').textContent=key==='home'?'Admin Dashboard':section?.[1]||'Admin Dashboard';heading.querySelector('p').textContent=section?.[2]||'';mobileTask.value=key;for(const [k,p] of panels)p.classList.toggle('hidden',k!==key);document.querySelectorAll('[data-workspace]').forEach(b=>{b.classList.toggle('active',b.dataset.workspace===key);b.setAttribute('aria-pressed',String(b.dataset.workspace===key))})}
