document.addEventListener('click',e=>{const summary=e.target.closest('[data-earning-status]');if(summary){selectedEarningDay='';historyPage.earnings=1;activeEarningSource=summary.dataset.earningSource||'all';activeEarningStatus=summary.dataset.earningStatus||'all';activeEarningLevel='all';renderEarningHistory();el('earningsTable')?.scrollIntoView({behavior:'smooth',block:'start'});return}const src=e.target.closest('[data-earning-source]');if(src){selectedEarningDay='';historyPage.earnings=1;if(src.dataset.earningSource==='ecommerce'){go('ecommerce');return}activeEarningSource=src.dataset.earningSource;activeEarningStatus='all';activeEarningLevel='all';renderEarningHistory();return}const lvl=e.target.closest('[data-earning-level]');if(lvl){selectedEarningDay='';historyPage.earnings=1;activeEarningLevel=lvl.dataset.earningLevel==='all'?'all':Number(lvl.dataset.earningLevel);renderEarningHistory();return}const ef=e.target.closest('[data-ecom-filter]');if(ef){selectedEarningDay='';historyPage.earnings=1;activeEcommerceFilter=ef.dataset.ecomFilter;renderEarningHistory();const ecomTable=el('ecommerceRows');if(ecomTable)renderEcommerceRows(ecomTable,activeEcommerceFilter);document.querySelectorAll('[data-ecom-filter]').forEach(b=>{const active=b.dataset.ecomFilter===activeEcommerceFilter;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});return}const er=e.target.closest('.view-ecommerce');if(er){const row=(window.memberEcommerceRows||[])[Number(er.dataset.index)];if(row)showEcommerceReceipt(row);return}});
function earningRows(){return window.memberBonusRows||[]}
function sourceLabel(source){return({all:'All earnings',team_bonus:'Team bonus',direct:'Direct',generation:'Generation',binary_pool_share:'Binary',single_line:'Binary placement earning',ecommerce:'E-commerce'})[source]||'Earnings'}
function sourceAmount(source){const teamMethods=['direct','generation','binary_pool_share','single_line'];const bonus=earningRows().filter(x=>(source==='all'||(source==='team_bonus'?teamMethods.includes(x.method):x.method===source))&&x.status==='posted').reduce((n,x)=>n+Number(x.payable_amount||0),0);const eco=(window.memberEcommerceRows||[]).filter(x=>x.status==='posted'&&(source==='ecommerce')).reduce((n,x)=>n+Number(x.amount||0),0);return bonus+eco}
function earningTrace(row){const value=row?.calculation_trace||{};if(typeof value!=='string')return value;try{return JSON.parse(value)}catch{return {}}}
function earningMobileLedger(rows,source='all'){
 if(!rows.length)return '<div class="earning-mobile-empty"><span>◎</span><h3>No matching earnings</h3><p>Try another date range or earning type.</p></div>';
 const sorted=[...rows].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),groups=new Map();for(const row of sorted){const day=historyDay(row.created_at);if(!groups.has(day))groups.set(day,[]);groups.get(day).push(row)}
 const presentation=row=>{const trace=earningTrace(row),eco=!!row.reward_kind,method=eco?'ecommerce':row.method,amount=earningAmount(row),held=isHeldEarning(row),time=new Date(row.created_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),rate=row.rate==null?'':(Number(row.rate)*100).toFixed(2).replace(/\.00$/,'')+'%',member=row.source_name||(method==='binary_pool_share'?'Binary share pool':'Member unavailable'),code=row.source_code||'',pkg=row.source_package_code?planName(row.source_package_code):'',base=Number(row.qualifying_base||0).toFixed(2),level=Number(row.generation||1);let icon='E',title=eco?ecommerceKind(row.reward_kind):bonusDisplayLabel(row),subtitle=[member,code].filter(Boolean).join(' · '),detail='Recorded earning';
  if(method==='direct'){icon=title.startsWith('Welcome')?'W':'D';detail=['Direct',base+' DP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(method==='generation'){icon='G'+level;detail=['Level '+level,base+' GP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(method==='binary_pool_share'){const shares=Number(trace.completed_shares||0),price=Number(trace.share_price??trace.gross_share_value??(shares?amount/shares:0)),matched=Number(trace.consumed_each_side||0);icon='BS';detail=`${matched.toFixed(2)} BP matched`;subtitle=`${shares.toFixed(2)} share${shares===1?'':'s'} × ${price.toFixed(2)} MIO`}
  else if(method==='single_line'){icon='P'+level;detail=['Level '+level,base+' BP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(eco){icon='EC';detail=[ecommerceLevel(row.reward_kind),Number(row.base_points||0).toFixed(2)+' points'].filter(Boolean).join(' · ');subtitle=[row.order_code||member,row.product_name_snapshot||code].filter(Boolean).join(' · ')}
  return {icon,title,subtitle,detail,amount,time,state:row.status==='posted'?'Credited':held?'On hold':'Reversed',stateClass:row.status==='posted'?'credited':held?'hold':'other'};
 };
 return `<div class="earning-mobile-ledger">${[...groups].map(([day,items])=>`<section class="earning-mobile-day"><header><span>${displayHistoryDay(day)}</span><small>${items.length} ${items.length===1?'entry':'entries'}</small></header><div class="earning-mobile-entries">${items.map(row=>{const item=presentation(row);return `<article class="earning-mobile-entry"><span class="earning-mobile-icon ${esc(item.stateClass)}">${esc(item.icon)}</span><div class="earning-mobile-main"><div class="earning-mobile-title"><strong>${esc(item.title)}</strong><b>+${item.amount.toFixed(2)} <small>MIO</small></b></div><p>${esc(item.subtitle)}</p><footer><span>${esc(item.time)}</span><em class="${esc(item.stateClass)}">${esc(item.state)}</em><span>${esc(item.detail)}</span></footer></div></article>`}).join('')}</div></section>`).join('')}</div>`;
}
function mobileEarningWeekBounds(reference=new Date()){
 const today=historyDay(reference),cursor=new Date(today+'T00:00:00Z'),daysSinceFriday=(cursor.getUTCDay()+2)%7,currentStart=new Date(cursor);currentStart.setUTCDate(cursor.getUTCDate()-daysSinceFriday);const currentEnd=new Date(currentStart);currentEnd.setUTCDate(currentStart.getUTCDate()+7);const lastStart=new Date(currentStart);lastStart.setUTCDate(currentStart.getUTCDate()-7);const iso=date=>date.toISOString().slice(0,10);return {current:{start:iso(currentStart),end:iso(currentEnd)},last:{start:iso(lastStart),end:iso(currentStart)},total:{start:'',end:''}};
}
function mobileEarningCategory(row){if(row?.reward_kind)return'ecommerce';if(row?.method==='direct')return bonusDisplayLabel(row).startsWith('Welcome')?'welcome_bonus':'direct';return({generation:'generation',single_line:'single_line',binary_pool_share:'binary_pool_share'})[row?.method]||'other'}
function mobileEarningPeriodRows(rows,period=activeMobileEarningPeriod,reference=new Date()){if(period==='custom')return filterHistoryDates(rows,'earnings');const bounds=mobileEarningWeekBounds(reference)[period]||mobileEarningWeekBounds(reference).current;if(period==='total')return rows;return rows.filter(row=>{const day=historyDay(row.created_at);return day>=bounds.start&&day<bounds.end})}
function mobileEarningPeriodLabel(period=activeMobileEarningPeriod,reference=new Date()){const short=value=>new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));if(period==='custom'){const {from,to}=historyFilters.earnings;return from||to?`${from?short(from):'First record'} – ${to?short(to):'Today'}`:'Choose a date range'}if(period==='total')return'All recorded dates';const bounds=mobileEarningWeekBounds(reference)[period],last=new Date(bounds.end+'T00:00:00Z');last.setUTCDate(last.getUTCDate()-1);return`${short(bounds.start)} – ${short(last.toISOString().slice(0,10))}`}
function mobileEarningCycles(reference=new Date()){
 const all=[...earningRows(),...(window.memberEcommerceRows||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),periodRows=mobileEarningPeriodRows(all,activeMobileEarningPeriod,reference),credited=periodRows.filter(row=>row.status==='posted'),held=periodRows.filter(isHeldEarning),categories=[['direct','D','Direct sponsor'],['welcome_bonus','W','Welcome bonus'],['generation','G','Generation bonus'],['single_line','P','Binary placement'],['binary_pool_share','BS','Binary share'],['ecommerce','EC','E-commerce']],tabs=[['current','Current week'],['last','Last week'],['total','Total history']],category=categories.find(item=>item[0]===activeMobileEarningCategory),selected=category?periodRows.filter(row=>mobileEarningCategory(row)===category[0]):[];
 const header=`<section class="mobile-earning-cycle"><div class="mobile-cycle-heading"><div><small>${activeMobileEarningPeriod==='current'?'Live earning cycle':activeMobileEarningPeriod==='last'?'Closed earning cycle':'Lifetime earning ledger'}</small><h3>${mobileEarningPeriodLabel(activeMobileEarningPeriod,reference)}</h3></div><span>Pakistan time</span></div><div class="mobile-cycle-total"><span>Total credited</span><strong>${sumEarnings(credited).toFixed(2)} <small>MIO</small></strong><p>${credited.length} credited ${credited.length===1?'entry':'entries'} · ${sumEarnings(held).toFixed(2)} MIO on hold</p></div></section>`;
 const nav=`<div class="mobile-cycle-tabs" role="tablist" aria-label="Earning history period">${tabs.map(([key,label])=>`<button type="button" role="tab" aria-selected="${activeMobileEarningPeriod===key}" class="${activeMobileEarningPeriod===key?'active':''}" data-mobile-earning-period="${key}">${label}</button>`).join('')}</div><details class="mobile-custom-dates" ${activeMobileEarningPeriod==='custom'?'open':''}><summary><span>Search custom dates</span><small>${activeMobileEarningPeriod==='custom'?mobileEarningPeriodLabel('custom',reference):'From and To date'}</small></summary>${historyDateControls('earnings')}</details>`;
 if(category){const selectedCredited=selected.filter(row=>row.status==='posted'),paged=pagedHistory(selected,'earnings');return`<section class="mobile-earning-cycles">${nav}${header}<div class="mobile-earning-detail-head"><button type="button" data-mobile-earning-back aria-label="Back to earning categories">←</button><div><small>${mobileEarningPeriodLabel(activeMobileEarningPeriod,reference)}</small><h3>${category[2]}</h3></div><strong>${sumEarnings(selectedCredited).toFixed(2)} <small>MIO</small></strong></div>${earningMobileLedger(paged,category[0])}${historyPagination(selected.length,'earnings')}</section>`}
 return`<section class="mobile-earning-cycles">${nav}${header}<div class="mobile-category-heading"><div><h3>Earning breakdown</h3><p>Tap a category to view members and calculations.</p></div><span>${periodRows.length} records</span></div><div class="mobile-earning-category-list">${categories.map(([key,icon,label])=>{const rows=periodRows.filter(row=>mobileEarningCategory(row)===key),posted=rows.filter(row=>row.status==='posted');return`<button type="button" class="mobile-earning-category" data-mobile-earning-category="${key}"><span class="mobile-category-icon">${icon}</span><span><strong>${label}</strong><small>${posted.length} credited ${posted.length===1?'entry':'entries'}</small></span><b>${sumEarnings(posted).toFixed(2)} <small>MIO</small></b><i>›</i></button>`}).join('')}</div>${periodRows.length?'':'<div class="earning-mobile-empty"><span>◎</span><h3>No earnings in this period</h3><p>New earnings will appear here automatically.</p></div>'}</section>`;
}
document.addEventListener('click',event=>{const period=event.target.closest('[data-mobile-earning-period]');if(period){activeMobileEarningPeriod=period.dataset.mobileEarningPeriod;activeMobileEarningCategory='all';historyFilters.earnings={from:'',to:''};historyPage.earnings=1;renderEarningHistory();return}const category=event.target.closest('[data-mobile-earning-category]');if(category){activeMobileEarningCategory=category.dataset.mobileEarningCategory;historyPage.earnings=1;renderEarningHistory();return}if(event.target.closest('[data-mobile-earning-back]')){activeMobileEarningCategory='all';historyPage.earnings=1;renderEarningHistory()}});
function renderEarningHistory(){
 const target=el('earningsTable');if(!target)return;
 el('earningSourceTabs')?.querySelectorAll('[data-earning-source]').forEach(button=>{const key=button.dataset.earningSource,active=key===activeEarningSource;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.innerHTML=`${esc(sourceLabel(key))}<b>${sourceAmount(key).toFixed(2)} MIO</b>`});
 const source=activeEarningSource,title=el('earningHistoryTitle'),hint=el('earningHistoryHint'),levels=el('earningLevelTabs'),ecom=el('earningEcommerceFilters');
 if(title)title.textContent=source==='ecommerce'?'E-commerce earnings':sourceLabel(source)+' history';
 if(ecom){ecom.hidden=source!=='ecommerce';ecom.classList.toggle('hidden',source!=='ecommerce');if(source==='ecommerce')ecom.innerHTML=renderEcommerceFilterTabs()}
 const allowed=earningLevels(source),showLevels=['generation','single_line'].includes(source)&&allowed.length>0;
 if(levels){levels.classList.toggle('hidden',!showLevels);levels.innerHTML=showLevels?`<span>Package levels</span><button class="${activeEarningLevel==='all'?'active':''}" data-earning-level="all">All levels</button>${allowed.map(n=>`<button class="${String(activeEarningLevel)===String(n)?'active':''}" data-earning-level="${n}">Level ${n}</button>`).join('')}`:''}
 if(source==='ecommerce'){if(hint)hint.textContent='Choose an earning type and date range. A total receipt is at the end of this history.';renderEcommerceRows(target,activeEcommerceFilter);enhanceResponsiveTables(target);return}
 let rows=[...earningRows()];
 if(source==='team_bonus')rows=rows.filter(x=>['direct','generation','binary_pool_share','single_line'].includes(x.method));else if(source!=='all')rows=rows.filter(x=>x.method===source);
 // E-commerce has its own page and is not added to network earnings.
 if(activeEarningStatus==='hold')rows=rows.filter(isHeldEarning);else if(activeEarningStatus==='credited')rows=rows.filter(x=>x.status==='posted');
 if(showLevels&&activeEarningLevel!=='all'&&allowed.includes(Number(activeEarningLevel)))rows=rows.filter(x=>Number(x.generation||1)===Number(activeEarningLevel));else if(!showLevels)activeEarningLevel='all';
 rows=filterHistoryDates(rows,'earnings').sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
 if(hint)hint.textContent=source==='all'?'Daily network bonus summary. Open a date for its members; the period receipt is at the end.':source==='direct'?'Direct members, DP and the sponsor rate applied at the time of earning.':source==='binary_pool_share'?'Each distribution shows your shares, share price and matched BP.':'Choose a level and date range to see its members and earning calculations.';
 const pagedRows=source==='all'?pagedHistory([...new Set(rows.map(x=>historyDay(x.created_at)))],'earnings').flatMap(day=>rows.filter(row=>historyDay(row.created_at)===day)):pagedHistory(rows,'earnings');
 target.innerHTML=mobileEarningCycles()+`<div class="earning-desktop-controls">${historyDateControls('earnings')+earningPeriodSummary(rows)}</div><div class="earning-desktop-history">${source==='all'?dailyEarningTable(rows):earningDetailTable(pagedRows,source)}</div><div class="earning-mobile-legacy">${earningMobileLedger(pagedRows,source)}</div><div class="earning-desktop-pagination">${historyPagination(source==='all'?new Set(rows.map(x=>historyDay(x.created_at))).size:rows.length,'earnings')}</div>`;
 if(source==='all'&&selectedEarningDay){const selected=rows.filter(x=>historyDay(x.created_at)===selectedEarningDay);if(selected.length)target.insertAdjacentHTML('beforeend',`<section class="history-day-detail" id="earningDayDetails"><div class="history-detail-heading"><h3>${displayHistoryDay(selectedEarningDay)} · Earning details</h3><button class="btn small" data-close-earning-day>Close details</button></div>${earningDetailTable(selected,'all')}</section>`)}
 target.insertAdjacentHTML('beforeend',totalEarningReceiptAction(rows,source));
 enhanceResponsiveTables(target);
}

function earningLevels(source){if(source==='direct')return[1];const code=memberPackageCode||packages.find(p=>p.code===memberPackageCode)?.code;const plan=planRules?.plans?.[code];if(source==='generation'){const n=Number(plan?.max_generations??packages.find(p=>p.code===code)?.generations??1);return Array.from({length:Math.max(0,n-1)},(_,i)=>i+2)}if(source==='single_line'){const n=Number(plan?.single_line_levels??packages.find(p=>p.code===code)?.singleLevels??({BASIC_1:10,BASIC_2:15,ADVANCED_1:20,ADVANCED_2:25,PREMIUM:30}[code]||0));return Array.from({length:n},(_,i)=>i+1)}return[]}
function dateLabel(value){return value?new Date(value).toLocaleString():'—'}
function joiningDateLabel(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'long',year:'numeric'}).format(date)}
function ecommerceLevel(kind){return({sponsor:'Level 1',second_sponsor:'Level 2'})[kind]||''}
function renderEcommerceFilterTabs(){const rows=window.memberEcommerceRows||[],sum=fn=>rows.filter(fn).reduce((n,x)=>n+Number(x.amount||0),0),items=[['credited','Total credited',sum(x=>x.status==='posted')],['hold','On hold',sum(x=>['pending_delivery','held_activation'].includes(x.status))],['cashback','Self-shopping cashback',sum(x=>x.reward_kind==='cashback')],['affiliate','Affiliate-link sales',sum(x=>x.reward_kind==='affiliate')]];return items.map(([key,label,value])=>`<button type="button" role="tab" aria-selected="${activeEcommerceFilter===key}" class="ecommerce-filter-tab ${activeEcommerceFilter===key?'active':''}" data-ecom-filter="${key}"><span>${label}</span><b>${value.toFixed(2)} MIO</b></button>`).join('')}
function renderEcommerceRows(target,filter='credited'){let rows=window.memberEcommerceRows||[];if(filter==='credited')rows=rows.filter(x=>x.status==='posted');else if(filter==='hold')rows=rows.filter(isHeldEarning);else if(filter==='cashback')rows=rows.filter(x=>x.reward_kind==='cashback');else if(filter==='affiliate')rows=rows.filter(x=>x.reward_kind==='affiliate');rows=filterHistoryDates(rows,'earnings').sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const paged=pagedHistory(rows,'earnings');target.innerHTML=historyDateControls('earnings')+earningPeriodSummary(rows)+`<div class="earning-desktop-history">${earningDetailTable(paged,'ecommerce')}</div>`+earningMobileLedger(paged,'ecommerce')+historyPagination(rows.length,'earnings')+totalEarningReceiptAction(rows,'ecommerce');enhanceResponsiveTables(target)}

function totalEarningReceiptAction(rows,source){const credited=sumEarnings(rows.filter(x=>x.status==='posted')),held=sumEarnings(rows.filter(isHeldEarning));return `<div class="earning-total-action"><div><small>Selected period · ${rows.length} entries</small><strong>Total credited: ${credited.toFixed(2)} MIO</strong><span>On hold: ${held.toFixed(2)} MIO · Held amounts are excluded from the credited total.</span></div><button type="button" class="btn primary" data-earning-total-receipt="${esc(source)}">Total earnings receipt</button></div>`}
function filteredEarningReceiptRows(){let rows=activeEarningSource==='ecommerce'?[...(window.memberEcommerceRows||[])]:[...earningRows()];if(activeEarningSource==='ecommerce'){if(activeEcommerceFilter==='credited')rows=rows.filter(x=>x.status==='posted');else if(activeEcommerceFilter==='hold')rows=rows.filter(isHeldEarning);else if(activeEcommerceFilter==='cashback')rows=rows.filter(x=>x.reward_kind==='cashback');else if(activeEcommerceFilter==='affiliate')rows=rows.filter(x=>x.reward_kind==='affiliate')}else{if(activeEarningSource==='team_bonus')rows=rows.filter(x=>['direct','generation','binary_pool_share','single_line'].includes(x.method));else if(activeEarningSource!=='all')rows=rows.filter(x=>x.method===activeEarningSource);if(activeEarningStatus==='hold')rows=rows.filter(isHeldEarning);else if(activeEarningStatus==='credited')rows=rows.filter(x=>x.status==='posted');if(['generation','single_line'].includes(activeEarningSource)&&activeEarningLevel!=='all')rows=rows.filter(x=>Number(x.generation||1)===Number(activeEarningLevel))}return filterHistoryDates(rows,'earnings')}
function showTotalEarningsReceipt(){if(!session)return;const rows=filteredEarningReceiptRows(),credited=rows.filter(x=>x.status==='posted'),held=rows.filter(isHeldEarning),groups=new Map();for(const row of rows){const key=row.reward_kind?'ecommerce':row.method||'other',entry=groups.get(key)||{credited:[],held:[]};if(row.status==='posted')entry.credited.push(row);else if(isHeldEarning(row))entry.held.push(row);groups.set(key,entry)}const filter=historyFilters.earnings||{},period=filter.from||filter.to?`${filter.from||'First record'} to ${filter.to||'Today'}`:'All recorded dates',label=activeEarningSource==='ecommerce'?`${sourceLabel('ecommerce')} · ${activeEcommerceFilter}`:sourceLabel(activeEarningSource),level=activeEarningLevel==='all'?'All eligible levels':'Level '+activeEarningLevel,lines=[...groups].map(([key,value])=>`<tr><th>${esc(sourceLabel(key))}</th><td>${value.credited.length+value.held.length}</td><td>${sumEarnings(value.credited).toFixed(2)}</td><td>${sumEarnings(value.held).toFixed(2)}</td></tr>`).join('');openHistoryDialog('Total earnings receipt',`${brandHeader('EARNINGS STATEMENT','Total earnings',label+' · '+period,'network')}<div class="receipt-statement-meta">${receiptGrid([{label:'Member',value:profile?.full_name||'Member'},{label:'Member code',value:profile?.member_code||'—',code:true},{label:'Period',value:period},{label:'Earning category',value:label},{label:'Level',value:level},{label:'Generated on',value:dateLabel(new Date())}])}</div><table class="receipt-statement-table"><thead><tr><th>Earning source</th><th>Entries</th><th>Credited MIO</th><th>On hold MIO</th></tr></thead><tbody>${lines||'<tr><td colspan="4">No earnings in this selection.</td></tr>'}</tbody><tfoot><tr><th>Total</th><td>${rows.length}</td><td>${sumEarnings(credited).toFixed(2)}</td><td>${sumEarnings(held).toFixed(2)}</td></tr></tfoot></table><div class="receipt-statement-total"><span>Total credited</span><strong>${sumEarnings(credited).toFixed(2)} MIO</strong></div><p class="receipt-footnote">This statement summarizes the selected earning history from your account ledger. On-hold rewards are shown separately and are not included in the credited total. It is not a cash payment receipt.</p>`)}
document.addEventListener('click',event=>{if(event.target.closest('[data-earning-total-receipt]'))showTotalEarningsReceipt()});
