function orderStatus(status){return ({placed:'Pending',confirmed:'Accepted',processing:'Processing',shipped:'Shipped',delivered:'Delivered',cancelled:'Cancelled',returned:'Returned'})[status]||esc(status)}
function heldPPV(o){return o.reward_mode==='MIO'||(o.selling_affiliate_id&&o.reward_owner_id!==session?.user.id&&!isAdmin)||o.rewards_credited_at||Number(o.ppv_generated)>0||['cancelled','returned'].includes(o.status)?0:(o.order_items||[]).reduce((v,i)=>v+Number(i.ppv_per_unit_snapshot||0)*Number(i.quantity),0)}
async function renderOrder(id){const target=el('orderDetail');target.innerHTML='<p>Loading order…</p>';const guest=guestOrderFromRoute(id);if(guest&&!session){try{const o=await fetchGuestOrder(guest),stages=['placed','confirmed','processing','shipped','delivered'],approval=o=>({pending:'Awaiting selling member approval',approved:'Selling member approved · 2 MIO safely on hold',released:'Delivered and paid · 2 MIO hold returned',rejected:'Selling member rejected this order',cancelled_refunded:'Order closed · 2 MIO hold returned'})[o.sponsor_approval_status]||'';target.innerHTML=`<div class="heading"><div><h1>Order ${esc(o.order_code)}</h1><p>Placed ${new Date(o.created_at).toLocaleString()} · Guest checkout</p></div><a class="btn" href="#orders">My orders</a></div><article class="card card-body"><span class="pill">${orderStatus(o.status)}</span><ol class="order-stages">${stages.map((v,i)=>`<li class="${i<=stages.indexOf(o.status)?'complete':''}">${orderStatus(v)}</li>`).join('')}</ol><p>Payment: <strong>${esc(o.payment_method)} · ${esc(o.payment_status)}</strong></p>${o.affiliate_attributed?`<p class="note"><strong>${esc(approval(o))}</strong><br>Affiliate checkout is guest-only and never creates a member account.</p>`:'<p class="note">Guest checkout does not create PPV, MIO wallet, or a team account.</p>'}<h2>Items</h2>${(o.items||[]).map(i=>`<div class="list-row"><span>${esc(i.product_name_snapshot||'Product')} × ${Number(i.quantity)}</span><b>${money(i.line_total_pkr??Number(i.unit_price_pkr)*Number(i.quantity))}</b></div>`).join('')}<p><strong>Total: ${money(o.total_pkr)}</strong></p><h2>Delivery</h2><p>${esc(o.shipping_name)} · ${esc(o.shipping_phone)}</p><p>${esc(o.shipping_address)} · ${esc(o.shipping_city)}</p></article>`}catch(error){target.innerHTML='<div class="empty"><h3>Guest receipt unavailable</h3><p>Use the same browser where this order was placed.</p></div>'}return}const uid=session?.user.id;if(!uid){target.innerHTML='<p>Sign in to view your order.</p>';return}const {data:o,error}=await db.from('orders').select('*,order_items(*)').eq('id',id).maybeSingle();if(session?.user.id!==uid||location.hash!==`#order/${id}`)return;if(error||!o){target.innerHTML='<p>Order unavailable.</p>';return}const stages=['placed','confirmed','processing','shipped','delivered'];target.innerHTML=`<div class="heading"><div><h1>Order ${esc(o.order_code)}</h1><p>Placed ${new Date(o.created_at).toLocaleString()}</p></div><a class="btn" href="#orders">My orders</a></div><article class="card card-body"><span class="pill">${orderStatus(o.status)}</span><ol class="order-stages">${stages.map((v,i)=>`<li class="${i<=stages.indexOf(o.status)?'complete':''}">${orderStatus(v)}</li>`).join('')}</ol><p>Payment: <strong>${esc(o.payment_status)}</strong></p>${!['placed','cancelled','returned'].includes(o.status)?'<button class="btn primary view-order-voucher" data-voucher-type="customer" data-id="'+esc(o.id)+'">View customer receipt</button>':''}<p class="note">${o.reward_mode==='MIO'?'E-commerce mode · No PPV. Total MIO reward budget: '+Number(o.reward_ppv_total||0).toFixed(2):o.selling_affiliate_id?'Affiliate-linked order · personal PPV goes to the selling affiliate.':''}</p><p class="note">PPV on hold: <strong>${heldPPV(o).toFixed(2)}</strong> · PPV credited: <strong>${o.selling_affiliate_id&&o.reward_owner_id!==uid&&!isAdmin?'0.00':Number(o.ppv_generated||0).toFixed(2)}</strong></p><p>${o.rewards_credited_at?'Rewards credited '+new Date(o.rewards_credited_at).toLocaleString():['cancelled','returned'].includes(o.status)?'No pending PPV for this order.':'Rewards remain on hold until delivery and payment confirmation. MIO details are available in E-commerce earnings.'}</p><h2>Items</h2>${(o.order_items||[]).map(i=>`<div class="list-row"><span>${esc(i.product_name_snapshot||i.product_name||'Product')} × ${Number(i.quantity)}</span><b>${money(i.unit_price_pkr* i.quantity)}</b></div>`).join('')}<p><strong>Total: ${money(o.total_pkr)}</strong></p><h2>Delivery</h2><p>${esc(o.shipping_name)} · ${esc(o.shipping_phone)}</p><p>${esc(o.shipping_address)} · ${esc(o.shipping_city)}</p></article>`}

