if(sellingQuery.get('affiliate')){sessionStorage.setItem('mio-selling-link',JSON.stringify({code:sellingQuery.get('affiliate'),expires:Date.now()+86400000*7}));const clean=new URL(location.href);clean.searchParams.delete('ref');if(clean.hash==='#join'||!clean.hash)clean.hash='shop';history.replaceState(null,'',clean)}
if(sellingQuery.get('vendor'))sessionStorage.setItem('mio-vendor-invite',sellingQuery.get('vendor'));
function currentSellingCode(){try{const a=JSON.parse(sessionStorage.getItem('mio-selling-link')||'null');if(!a||a.expires<Date.now())return '';return a.code===profile?.member_code?'':a.code}catch{return ''}}
