function sellingLinks(){if(!profile||isAdmin)return '';const url=new URL(location.origin+location.pathname);url.searchParams.set('affiliate',profile.member_code);url.hash='shop';const vendor=new URL(location.origin+location.pathname);vendor.searchParams.set('vendor',profile.member_code);vendor.hash='sell';return `<div class="selling-links"><h3>Selling & vendor invitations</h3><p>Your affiliate link opens the Marketplace for guest checkout only. It can never register a member or add anyone to your team.</p><button class="btn primary copy-code" data-copy="${esc(url.href)}">Copy marketplace selling link</button> <button class="btn copy-code" data-copy="${esc(vendor.href)}">Copy vendor invitation</button><p class="helper">Affiliate guest orders need your approval. Approval places a refundable 2 MIO hold from your Cash Wallet; it returns after delivery and confirmed payment.</p></div>`}
function productRewardText(p){const base=Number(p.ppv_per_unit||0);if(currentSellingCode())return '<strong class="ppv-callout">Affiliate reward goes to the seller</strong><small class="ppv-help">Your product discount is shown above.</small>';const mio=profile?.shopping_reward_mode==='MIO'&&hasApprovedPackage,amount=mio?(Math.trunc(base*.65*10000)/10000).toFixed(2):base.toFixed(2),unit=mio?'MIO cashback':'PPV';return `<strong class="ppv-callout">${amount} ${unit} per item</strong><small class="ppv-help">Credited after delivery and confirmed payment.</small>`}
