function applyTreeFilter(){activeTreeFilter={package:el('treeFilterPackage').value,status:el('treeFilterStatus').value};for(const button of el('networkVisual').querySelectorAll('.visual-person')){const n=treeNodes.find(x=>String(x.id)===button.dataset.treeInfo);if(!n)continue;const match=(!activeTreeFilter.package||n.package===activeTreeFilter.package)&&(!activeTreeFilter.status||String(n.status||'').toLowerCase()===activeTreeFilter.status);button.closest('.visual-node')?.classList.toggle('tree-filter-dim',!match)}}

function binaryQualificationCard(n){const qualified=Boolean(n.binary_qualified),leftDirects=Number(n.left_direct_count||0),rightDirects=Number(n.right_direct_count||0),leftDp=Number(n.left_dp||0),rightDp=Number(n.right_dp||0),reqDp=20;return `<section class="binary-qualification ${qualified?'is-qualified':'is-pending'}"><div class="binary-qualification-head"><span class="binary-status-mark">${qualified?'✓':'!'}</span><div><small>One-time Binary qualification</small><h4>${qualified?'Binary Active':'Binary Inactive'}</h4></div>${qualified&&n.binary_qualified_at?`<time>${joiningDateLabel(n.binary_qualified_at)}</time>`:''}</div><div class="binary-qualification-grid"><div class="${leftDirects>=1?'complete':''}"><small>Left Direct</small><strong>${leftDirects}/1</strong></div><div class="${rightDirects>=1?'complete':''}"><small>Right Direct</small><strong>${rightDirects}/1</strong></div><div class="${leftDp>=reqDp?'complete':''}"><small>Left DP</small><strong>${leftDp.toFixed(2)}/20</strong></div><div class="${rightDp>=reqDp?'complete':''}"><small>Right DP</small><strong>${rightDp.toFixed(2)}/20</strong></div></div><p>${qualified?'Qualification completed permanently. Weekly requalification is not required.':'Complete one active personal direct and 20 DP on both LEFT and RIGHT sides.'}</p></section>`}
function treeMemberInformation(n){const kind=el('networkKind').value,level=Number(n.level||n.depth||0),children=treeNodes.filter(x=>x.parent_id===n.id).length,left=Number(n.left_bp||0),right=Number(n.right_bp||0),totalLeft=Number(n.total_left_bp??left),totalRight=Number(n.total_right_bp??right),hasSideBrp=['total_left_brp','left_brp','total_right_brp','right_brp'].some(k=>Object.hasOwn(n,k)),totalLeftBrp=Number(n.total_left_brp??n.left_brp??0),totalRightBrp=Number(n.total_right_brp??n.right_brp??0),legacyBrp=Number(n.brp??n.binary_rank_points??0),leftTeam=Number(n.left_team_count||0),rightTeam=Number(n.right_team_count||0),shareBp=Math.max(.0001,Number(n.binary_share_points_each_side||planRules?.binary_share_points_each_side||50)),rawShares=Math.floor(Math.min(left,right)/(shareBp/10))/10,packageRate=Math.max(0,Number(n.binary_entitlement??1)),availableShares=n.available_binary_shares==null?rawShares*packageRate:Number(n.available_binary_shares);
 if(kind==='generation')return `<div id="generationMemberSummary" class="generation-member-summary"><div class="generation-summary-loading"><span></span><p>Loading generation information…</p></div></div>`;
 if(kind==='single_line')return `<div id="placementMemberSummary" class="generation-member-summary"><div class="generation-summary-loading"><span></span><p>Loading 30-level placement information…</p></div></div>`;
 if(kind==='vendor'||n.node_type==='vendor')return `<div class="tree-binary-summary"><section><h4>Vendor information</h4><div class="tree-detail-stats"><div><small>Store</small><strong>${esc(n.business_name||n.full_name)}</strong></div><div><small>Status</small><strong>${esc(n.status||'Active')}</strong></div><div class="wide"><small>Agreed commission</small><strong>${(Number(n.commission_rate||0)*100).toFixed(2)}%</strong></div></div></section></div>`;
 return `<div class="tree-binary-summary">${binaryQualificationCard(n)}<section><h4>Binary team</h4><div class="tree-detail-stats"><div><small>Left Team</small><strong>${leftTeam}</strong></div><div><small>Right Team</small><strong>${rightTeam}</strong></div></div></section><section><h4>Carry Forward BP</h4><div class="tree-detail-stats"><div><small>Left BP</small><strong>${left.toFixed(2)}</strong></div><div><small>Right BP</small><strong>${right.toFixed(2)}</strong></div><div class="wide tree-week-shares"><small>Available binary shares</small><strong>${availableShares.toFixed(1)}</strong><span>${rawShares.toFixed(1)} raw × ${(packageRate*100).toFixed(0)}% ${esc(planName(n.package))} rate · ${shareBp.toFixed(2)} matched BP per side</span></div></div></section><section><h4>TNBP <small>Total Network Binary Points till now</small></h4><div class="tree-detail-stats"><div><small>Total Left BP</small><strong>${totalLeft.toFixed(2)}</strong></div><div><small>Total Right BP</small><strong>${totalRight.toFixed(2)}</strong></div></div></section>${hasSideBrp?`<section><h4>BRP <small>Binary Rank Points till now</small></h4><div class="tree-detail-stats"><div><small>Total Left BRP</small><strong>${totalLeftBrp.toFixed(2)}</strong></div><div><small>Total Right BRP</small><strong>${totalRightBrp.toFixed(2)}</strong></div></div></section>`:`<section><h4>BRP <small>Binary Rank Points</small></h4><div class="tree-detail-stats"><div class="wide"><small>Current BRP</small><strong>${legacyBrp.toFixed(2)}</strong></div></div></section>`}</div>`}

async function loadPlacementMemberDetails(n){const host=el('placementMemberSummary');if(!host)return;const {data,error}=await db.rpc('member_binary_placement_details',{p_member_code:n.member_code});if(error)throw error;if(!host.isConnected||selectedTreeNodeId!==n.id)return;const allowed=Number(data?.allowed_levels||0),levels=data?.levels||[];host.innerHTML=`<section class="placement-information"><div class="placement-info-title"><div><small>Binary Placement information</small><h4>${esc(data.package_name||planName(n.package))} active</h4></div><span>${allowed}/30 earning levels</span></div><div class="placement-team-grid"><div><small>Total Placement Team</small><strong>${Number(data.total_team||0)}</strong></div><div><small>Left Team</small><strong>${Number(data.left_team||0)}</strong></div><div><small>Right Team</small><strong>${Number(data.right_team||0)}</strong></div></div><button type="button" class="generation-network-total" data-placement-panel><span><small>Level-wise Placement Team</small><strong>Levels 1–30</strong></span><b>View details ›</b></button><div class="placement-levels" data-placement-content hidden>${levels.map(row=>`<div class="placement-level-row ${row.earning_active?'active':'locked'}"><span><b>Level ${Number(row.level)}</b><small>${row.earning_active?'Earning active':'Visible · earning locked'}</small></span><strong>${Number(row.member_count||0)} members</strong><i aria-label="${row.earning_active?'Active':'Locked'}">${row.earning_active?'✓':'🔒'}</i></div>`).join('')}</div><p class="placement-note">All 30 levels remain visible. Only the ${allowed} levels allowed by this package generate Binary Placement earning.</p></section>`}
function generationMemberRows(rows=[]){return rows.length?`<div class="generation-member-list">${rows.map((m,i)=>{const avatar=safeImage(m.profile_photo_url)||`/assets/tree-avatar-${i%10+1}.svg`;return `<div class="generation-member-row"><img src="${avatar}" alt=""><span><strong>${esc(m.full_name||'Member')}</strong><small>${esc(m.member_code||'—')} · ${esc(planName(m.package))}</small></span><em>${esc(m.status||'Inactive')}</em></div>`}).join('')}</div>`:'<p class="generation-empty">No members in this generation.</p>'}
async function loadGenerationMemberDetails(n){const host=el('generationMemberSummary');if(!host)return;const {data,error}=await db.rpc('my_generation_member_details',{p_member_code:n.member_code});if(error)throw error;if(!host.isConnected||selectedTreeNodeId!==n.id)return;const generations=data?.generations||[],directs=data?.directs||[];host.innerHTML=`<section class="generation-information"><div class="generation-info-title"><div><small>Generation information</small><h4>${esc(data.package_name||planName(n.package))} active</h4></div><span>TNGP ${Number(data.tngp||0).toFixed(2)}</span></div><div class="generation-summary-grid"><button type="button" data-generation-panel="directs"><small>Directs</small><strong>${Number(data.direct_count||0)}</strong><span>${Number(data.active_direct_count||0)} active · View members</span></button><div><small>Direct Points</small><strong>${Number(data.direct_points||0).toFixed(2)} <i>DP</i></strong><span>Qualification points</span></div><div><small>TNGP</small><strong>${Number(data.tngp||0).toFixed(2)} <i>GP</i></strong><span>Total Network Generation Points</span></div><div><small>Active Generations</small><strong>${Number(data.active_generations||0)}/${Number(data.allowed_generations||0)}</strong><span>Package + directs + DP qualified</span></div></div><button type="button" class="generation-network-total" data-generation-panel="network"><span><small>Total Generation Network</small><strong>${Number(data.total_generation_network||0)} members</strong></span><b>View generation details ›</b></button><div class="generation-drilldown" data-generation-content="directs" hidden><div class="generation-drilldown-head"><h4>Direct Members</h4><span>${directs.length} members</span></div>${generationMemberRows(directs)}</div><div class="generation-drilldown" data-generation-content="network" hidden><div class="generation-drilldown-head"><h4>Generation Breakdown</h4><span>${Number(data.total_generation_network||0)} total members</span></div><div class="generation-breakdown">${generations.map(g=>`<button type="button" data-generation-level="${Number(g.level)}"><span><b>Generation ${Number(g.level)}</b><small>${g.unlocked?'Earning active':g.allowed?'Qualification pending':'Locked for package'}</small></span><strong>${Number(g.member_count||0)} ${g.unlocked?'✓':'🔒'}</strong></button><div class="generation-level-members" data-generation-members="${Number(g.level)}" hidden>${generationMemberRows(g.members||[])}</div>`).join('')}</div></div></section>`}
document.addEventListener('click',e=>{const panel=e.target.closest('[data-generation-panel]');if(panel){const host=panel.closest('.generation-information'),key=panel.dataset.generationPanel;host?.querySelectorAll('[data-generation-content]').forEach(section=>{const open=section.dataset.generationContent===key&&section.hidden;section.hidden=!open});return}const level=e.target.closest('[data-generation-level]');if(level){const list=level.nextElementSibling;if(list?.matches('[data-generation-members]')){list.hidden=!list.hidden;level.classList.toggle('open',!list.hidden)}}});
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-placement-panel]');if(!toggle)return;const content=toggle.closest('.placement-information')?.querySelector('[data-placement-content]');if(!content)return;content.hidden=!content.hidden;toggle.classList.toggle('open',!content.hidden);const label=toggle.querySelector('b');if(label)label.textContent=content.hidden?'View details ›':'Close details ⌃'});
el('treeFilterForm').addEventListener('submit',e=>{e.preventDefault();applyTreeFilter()});el('treeFilterForm').querySelector('[data-clear-tree-filter]').addEventListener('click',()=>{el('treeFilterPackage').value='';el('treeFilterStatus').value='';applyTreeFilter()});
el('treeSearchForm').addEventListener('submit',e=>{e.preventDefault();const query=el('treeSearchInput').value.trim();if(!query){el('treeSearchStatus').textContent='Enter a member code or name.';return}const lower=query.toLocaleLowerCase(),cleanCode=lower.replace(/^mio-/,'');const found=treeNodes.find(n=>String(n.member_code||'').toLocaleLowerCase().replace(/^mio-/,'')===cleanCode||String(n.full_name||'').toLocaleLowerCase().includes(lower));if(found){el('treeSearchStatus').textContent=`Found ${found.full_name}.`;const node=Array.from(el('networkVisual').querySelectorAll('[data-tree-info]')).find(x=>x.dataset.treeInfo===String(found.id));if(node){node.click();const rect=node.getBoundingClientRect(),box=el('networkVisual').getBoundingClientRect();el('networkVisual').scrollLeft+=rect.left-box.left- box.width/2+rect.width/2;el('networkVisual').scrollTop+=rect.top-box.top-box.height/2+rect.height/2}return}if(/^[a-z0-9-]{4,}$/i.test(query)){networkHistory.push(networkRoot);networkRoot=query.toUpperCase().startsWith('MIO-')?query.toUpperCase():'MIO-'+query.toUpperCase();el('treeSearchStatus').textContent='Loading that member’s permitted branch…';renderNetwork().then(()=>{if(!treeNodes.length)el('treeSearchStatus').textContent='No matching member is available in this tree.'}).catch(err=>{el('treeSearchStatus').textContent='Member branch could not be opened.';toast(err.message)});return}el('treeSearchStatus').textContent='No match in the loaded tree. Increase levels or search by member code.'});
let treePointers=new Map(),treeDragStart=null,treePinchStart=null;const treeViewport=el('networkVisual');
treeViewport.addEventListener('wheel',e=>{if(!e.target.closest('.tree-pan-surface'))return;e.preventDefault();const rect=treeViewport.getBoundingClientRect(),factor=e.deltaY<0?1.12:.89;setTreeZoom(treeZoom*factor,e.clientX-rect.left,e.clientY-rect.top)},{passive:false});
treeViewport.addEventListener('pointerdown',e=>{if(!e.target.closest('.tree-pan-surface')||(treePointers.size===0&&e.target.closest('button,input,select,a')))return;treePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});treeViewport.setPointerCapture?.(e.pointerId);treeViewport.classList.add('dragging');if(treePointers.size===1)treeDragStart={x:e.clientX,y:e.clientY,left:treeViewport.scrollLeft,top:treeViewport.scrollTop};if(treePointers.size===2){const pts=[...treePointers.values()];treePinchStart={distance:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),zoom:treeZoom}}});
treeViewport.addEventListener('pointermove',e=>{if(!treePointers.has(e.pointerId))return;treePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(treePointers.size===2&&treePinchStart){const pts=[...treePointers.values()],distance=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),rect=treeViewport.getBoundingClientRect();setTreeZoom(treePinchStart.zoom*distance/Math.max(1,treePinchStart.distance),(pts[0].x+pts[1].x)/2-rect.left,(pts[0].y+pts[1].y)/2-rect.top)}else if(treePointers.size===1&&treeDragStart){treeViewport.scrollLeft=treeDragStart.left-(e.clientX-treeDragStart.x);treeViewport.scrollTop=treeDragStart.top-(e.clientY-treeDragStart.y)}});
function endTreePointer(e){treePointers.delete(e.pointerId);if(treePointers.size<2)treePinchStart=null;if(treePointers.size===1){const p=[...treePointers.values()][0];treeDragStart={x:p.x,y:p.y,left:treeViewport.scrollLeft,top:treeViewport.scrollTop}}if(!treePointers.size){treeDragStart=null;treeViewport.classList.remove('dragging')}}treeViewport.addEventListener('pointerup',endTreePointer);treeViewport.addEventListener('pointercancel',endTreePointer);

el('clearSellingLink').addEventListener('click',()=>{sessionStorage.removeItem('mio-selling-link');const u=new URL(location.href);u.searchParams.delete('affiliate');history.replaceState(null,'',u);loadEcommerce().catch(e=>toast(e.message))});

function rewardBreakdown(price,commission,awarded){const c=Number(commission||0),r=awarded==null?Math.max(0,c-.05):Number(awarded),p=Number(price||0);return `<div class="reward-breakdown"><span>Sale price <b>${money(p)}</b></span><span>Vendor ${(100-c*100).toFixed(2)}% <b>${money(p*(1-c))}</b></span><span>Company 5% <b>${money(p*.05)}</b></span><span>Awarded ${(r*100).toFixed(2)}% <b>${money(p*r)} ÷ 300 = ${(Math.floor((p*r/300+1e-10)*10000)/10000).toFixed(2)} points</b></span><span>Company leftover ${Math.max(0,(c-.05-r)*100).toFixed(2)}% <b>${money(p*Math.max(0,c-.05-r))}</b></span></div>`}
function productPriceBreakdown(base,sale,commission,awarded){base=Number(base||0);sale=Number(sale||0);commission=Number(commission||0);const discount=Math.max(base-sale,0),available=Math.max(0,commission-.05-discount/(base||1)),rate=awarded==null?available:Number(awarded),awardAmount=base*rate,leftover=base*Math.max(0,available-rate);return `<div class="reward-breakdown"><span>Vendor submitted / reward base <b>${money(base)}</b></span><span>Customer sale price <b>${money(sale)}${discount?` · discount ${money(discount)}`:''}</b></span><span>Fixed company 5% <b>${money(base*.05)}</b></span><span>Remaining budget <b>${(available*100).toFixed(2)}% · ${money(base*available)}</b></span><span>Awarded <b>${(rate*100).toFixed(2)}% · ${money(awardAmount)} ÷ 300 = ${(Math.floor((awardAmount/300+1e-10)*10000)/10000).toFixed(2)} PPV/MIO</b></span><span>Company extra leftover <b>${money(leftover)}</b></span></div>`}
function productAwardForm(p){const v=adminVendorRows.find(v=>v.id===p.vendor_id);if(!v)return '';return `<details class="plain-details" open><summary>Admin pricing & reward budget</summary><form class="product-award form" data-id="${p.id}" data-base="${p.vendor_submitted_price_pkr??p.price_pkr}" data-commission="${Number(v.commission_rate)}" data-vendor-award="${v.awarded_rate??''}"><p>Vendor submitted price: <strong>${money(p.vendor_submitted_price_pkr??p.price_pkr)}</strong></p><div class="row"><label>Website sale price<input name="sale" type="number" min="0.01" step="0.01" value="${Number(p.price_pkr)}" required></label><label>Crossed-out price (optional)<input name="compare" type="number" min="0.01" step="0.01" value="${p.compare_at_price_pkr??''}" placeholder="e.g. 1200"></label></div><label>Awarded percentage of vendor price<input name="awarded" type="number" min="0" max="${Math.max(0,Number(v.commission_rate)*100-5)}" step="0.0001" value="${p.awarded_rate_override==null?'':Number(p.awarded_rate_override)*100}" placeholder="Auto: full remaining budget"></label><p class="helper">A lower sale price reduces the reward budget. Crossed-out price is display only. Blank award uses all remaining budget; any amount you hold back goes to company.</p><div class="reward-formula-preview">${productPriceBreakdown(p.vendor_submitted_price_pkr??p.price_pkr,p.price_pkr,v.commission_rate,p.awarded_rate_override??v.awarded_rate)}</div><button class="btn small">Save pricing & reward</button></form></details>`}
document.addEventListener('input',e=>{const f=e.target.closest('.vendor-commission,.product-award');if(!f)return;const commission=f.matches('.vendor-commission')?Number(f.elements.commission.value)/100:Number(f.dataset.commission);if(f.matches('.vendor-commission')){f.elements.awarded.max=Math.max(0,commission*100-5);f.querySelector('.reward-formula-preview').innerHTML=rewardBreakdown(10000,commission,f.elements.awarded.value===''?null:Number(f.elements.awarded.value)/100);return}const base=Number(f.dataset.base),sale=Number(f.elements.sale.value),available=Math.max(0,commission-.05-Math.max(base-sale,0)/base),raw=f.elements.awarded.value,award=raw===''?(f.dataset.vendorAward===''?available:Number(f.dataset.vendorAward)):Number(raw)/100;f.elements.awarded.max=(available*100).toFixed(4);f.querySelector('.reward-formula-preview').innerHTML=productPriceBreakdown(base,sale,commission,award)});
document.addEventListener('submit',e=>{if(!e.target.matches('.product-award'))return;e.preventDefault();const f=e.target;submit(f,async()=>{const {error}=await db.rpc('admin_update_product_pricing',{p_product_id:f.dataset.id,p_sale_price:Number(f.elements.sale.value),p_compare_at:f.elements.compare.value===''?null:Number(f.elements.compare.value),p_awarded:f.elements.awarded.value===''?null:Number(f.elements.awarded.value)/100});if(error)throw error;toast('Pricing and reward budget saved');await loadAdmin();await loadCatalog()})});
